/*
 * Script Name: ExportDiagrams.ExportDiagrams-Helper
 * Author: Sergey Gaidamakov
 * Purpose: Вспомогательные функции для выгрузки диаграмм.
 * Date: 13.12.2024
 */

var ELEMENT_TYPES_WITH_DIAGRAMS = ["Class", "Interface", "Component", "StateMachine", "UseCase", "Requirement", "Feature", "Actor", "Activity", "Interaction"];

// Имя файла картинки
function GetDiagramImageFileName( aDiagram ) {
	var theDiagram as EA.Diagram;
	theDiagram = aDiagram;
	return theDiagram.DiagramGUID.slice(1,-1) + ".png";
}


// Имя файла картинки с номером версии
function GetDiagramVersionImageFileName( aDiagram ){
	var theDiagram as EA.Diagram;
	theDiagram = aDiagram;
	return theDiagram.DiagramGUID.slice(1,-1) + "_" + theDiagram.Version.replace(".", "_") + ".png";
}

// Путь к файлу картинки на локальном компьютере
function GetDiagramFullImageFileName( anExportPath, aDiagram ) {
	return MakeFilePath( anExportPath, "EA" + GetSlash(anExportPath) + "Diagrams" + GetSlash(anExportPath) + GetDiagramImageFileName( aDiagram ));
}

// Путь к файлу версии картинки на локальном компьютере
function GetDiagramFullVersionImageFileName( anExportPath, aDiagram ) {
	return MakeFilePath( anExportPath, "EA" + GetSlash(anExportPath) + "Diagrams" + GetSlash(anExportPath) + GetDiagramVersionImageFileName( aDiagram ));
}

// Путь к файлу картинки в Git репозитории
function GetDiagramGitImageFileName( aGitProjectPath, aDiagram ) {
	return MakeFilePath( aGitProjectPath, GetDiagramImageFileName(aDiagram));
}

// Путь к файлу версии картинки в Git репозитории
function GetDiagramGitVersionImageFileName( aGitProjectPath, aDiagram ) {
	return MakeFilePath( aGitProjectPath, GetDiagramVersionImageFileName(aDiagram));
}

// Имя PlantUML файла
function GetDiagramPlantUMLFileName( aDiagram ) {
	var theDiagram as EA.Diagram;
	theDiagram = aDiagram;
	return theDiagram.DiagramGUID.slice(1,-1) + ".puml";
}

// Имя файла PlantUML с номером версии
function GetDiagramVersionPlantUMLFileName( aDiagram ){
	var theDiagram as EA.Diagram;
	theDiagram = aDiagram;
	return theDiagram.DiagramGUID.slice(1,-1) + "_" + theDiagram.Version.replace(".", "_") + ".puml";
}

// Путь к файлу PlantUML на локальном компьютере
function GetDiagramFullPlantUMLFileName( anExportPath, aDiagram ) {
	return MakeFilePath( anExportPath, "EA" + GetSlash(anExportPath) + "Diagrams" + GetSlash(anExportPath) + GetDiagramPlantUMLFileName( aDiagram ));
}

// Путь к файлу версии PlantUML на локальном компьютере
function GetDiagramFullVersionPlantUMLFileName( anExportPath, aDiagram ) {
	return MakeFilePath( anExportPath, "EA" + GetSlash(anExportPath) + "Diagrams" + GetSlash(anExportPath) + GetDiagramVersionPlantUMLFileName( aDiagram ));
}

// Путь к файлу PluntUML в Git репозитории
function GetDiagramGitPlantUMLFileName( aGitProjectPath, aDiagram ) {
	return MakeFilePath( aGitProjectPath, GetDiagramPlantUMLFileName(aDiagram));
}

// Путь к файлу версии PlantUML в Git репозитории
function GetDiagramGitVersionPlantUMLFileName( aGitProjectPath, aDiagram ) {
	return MakeFilePath( aGitProjectPath, GetDiagramVersionPlantUMLFileName(aDiagram));
}

function GetElementPath( anElement ) {
	if (!anElement) {
		return "";
	}
	var theElement as EA.Element;
	theElement = anElement;
	if (theElement.ParentID) {
		if (theElement.Type) {
			var theParentElement as EA.Element;
			var theParentElement = Repository.GetElementByID(theElement.ParentID);
			return GetElementPath(theParentElement) + " \\ " + theElement.Name;
		} else {
			var theParentPackage as EA.Package;
			var theParentPackage = Repository.GetPackageByID(theElement.ParentID);
			return GetElementPath( theParentPackage ) + " \\ " + theElement.Name;
		}
	}
	if (theElement.PackageID && theElement.Type) {
		// У верхнего элемента нет ParentID и нет theElement.Type, чтобы не зациклились
		var theParentPackage as EA.Package;
		var theParentPackage = Repository.GetPackageByID(theElement.PackageID);
		return GetElementPath( theParentPackage ) + " \\ " + theElement.Name;
	}
	return theElement.Name;
}


function GetDefaultExportPathPropertyName() {
	return "DiagramExportPath";
}


function GetUserExportPathPropertyName() {
	return (Session.UserName ? Session.UserName + "_" + GetDefaultExportPathPropertyName() : GetDefaultExportPathPropertyName());
}

function GetExportPathForDiagram() {
	var exportPath = GetPropertyTypeValue( GetUserExportPathPropertyName() );
	if (!exportPath) {
		// Если не нашли путь, специфичный для текущего пользователя, то берем путь по умолчанию.
		exportPath = GetPropertyTypeValue( GetDefaultExportPathPropertyName() );
		LOGTrace("exportPath from <"+GetDefaultExportPathPropertyName() + "> = " + exportPath);
	}
	if (!exportPath) {
		Session.Prompt( "Not found 'Tagged value type' with name <"+GetDefaultExportPathPropertyName()+">. Define tagged value <"+GetDefaultExportPathPropertyName()+"> at menu 'Settings \\ Reference Data \\ UML Types'", promptOK );
		return null;
	}
	var result = Session.Prompt("Export diagrams to path '"+exportPath+"'" , promptYESNO);
	if (result != resultYes) {
		exportPath = Session.Input("Enter export diagrams path");
		if (!exportPath) {
			return;
		}
		// Сохраняем новое значение пути
		SetPropertyTypeValue( GetUserExportPathPropertyName(), exportPath, "Путь для экспорта диаграмм" );
		LOGTrace("exportPath saved to <"+GetUserExportPathPropertyName() + "> = " + exportPath);
	}
	return exportPath;
}

function GetDefaultGitProjectPropertyName() {
	return "DocumentationGitProject";
}


function GetUserGitProjectPropertyName() {
	return (Session.UserName ? Session.UserName + "_" + GetDefaultGitProjectPropertyName() : GetDefaultGitProjectPropertyName());
}

function GetGitProjectPath() {
	var gitPropertyName = GetUserGitProjectPropertyName();
	Session.Output("gitPropertyName = " + gitPropertyName);
	var gitProjectPath = GetPropertyTypeValue( gitPropertyName );
	if (gitProjectPath) {
		Session.Output("gitProjectPath = " + gitProjectPath);
	} else {
		Session.Output("gitProjectPath is empty");
	}
	return gitProjectPath;
}

function exportDiagramsFromElement( aProject, anExportPath, aGitProjectPath, anElement ) {
	var theElement as EA.Element;
	var diagramCount = 0;
	theElement = anElement;
	if (!theElement) {
		LOGTrace("!!! Function ExportDiagramsFromElement has got theElement == null.");
		return 0;
	}
	if (theElement.Type && !ELEMENT_TYPES_WITH_DIAGRAMS.includes(theElement.Type)){
		LOGTrace("Element <" + theElement.Name + "> has skipped type " + theElement.Type);
		return 0;
	}
	var elementPath = GetElementPath( theElement );
	if (IsDeletedElement(theElement)) {
		Session.Output( " " );
		Session.Output( "Element is deleted: " + elementPath );
		Session.Output( " " );
		return 0;
	}
	if (theElement.Diagrams) {
		for (var i=0; i < theElement.Diagrams.Count; i++){
			diagramCount += exportDiagramToGit( aProject, anExportPath, aGitProjectPath, elementPath, theElement.Diagrams.GetAt(i).DiagramID );
		}
	}
	if (theElement.Elements) {
		for (var i=0; i < theElement.Elements.Count; i++){
			diagramCount += exportDiagramsFromElement( aProject, anExportPath, aGitProjectPath, theElement.Elements.GetAt(i) );
		}
	}
	if (theElement.Packages) {
		for (var i=0; i < theElement.Packages.Count; i++){
			diagramCount += exportDiagramsFromElement( aProject, anExportPath, aGitProjectPath, theElement.Packages.GetAt(i) );
		}
	}
	return diagramCount;
}

// Выгрузка диаграммы с обновлением описания путей Git для всех типов
function exportDiagramToGit( aProject, anExportPath, aGitProjectPath, aPackagePath, aDiagramID) {
	// Remember the visibility of the diagram
	var currentDiagram as EA.Diagram;
	currentDiagram = Repository.GetCurrentDiagram();
	var currentDiagramID = (currentDiagram ? currentDiagram.DiagramID : -1);
	/*
	LOGTrace(" GetCurrentDiagram=" + currentDiagramID + ", aDiagram=" + aDiagram.DiagramID);
	*/
	var theDiagram as EA.Diagram;
	theDiagram = Repository.GetDiagramByID(aDiagramID);

	Session.Output(" ");
	var diagramCount = exportImageDiagramToGit( aProject, anExportPath, aGitProjectPath, aPackagePath, theDiagram );

	Session.Output(" ");
	diagramCount += exportPlantUMLDiagramToGit( aProject, anExportPath, aGitProjectPath, aPackagePath, theDiagram );

	if (currentDiagramID != aDiagramID) {
		// При сохранении в файл открывается закладка диаграммы и ее нужно закрыть:
		Repository.CloseDiagram(aDiagramID);
	} 

	return (diagramCount ? 1 : 0);
}


function exportImageDiagramToGit( aProject, anExportPath, aGitProjectPath, aPackagePath, aDiagram ) {
	var theDiagram as EA.Diagram;
	theDiagram = aDiagram;
	var diagramPath = aPackagePath + " \\ " + theDiagram.Name;

	if (IsDeletedDiagram(theDiagram)) {
		Session.Output( "Diagram is deleted: " + diagramPath );
		return 0;
	}

	var currentDiagram = Repository.GetCurrentDiagram();
	var currentDiagramID = (currentDiagram ? currentDiagram.DiagramID : -1);

	var theProject as EA.Project;
	theProject = aProject;
	var fileName = GetDiagramFullImageFileName( anExportPath, theDiagram );
	var versionFileName = GetDiagramFullVersionImageFileName( anExportPath, theDiagram );

	if (!theProject.PutDiagramImageToFile(theDiagram.DiagramGUID, fileName, 1)) {
		var errorMessage = "Can not export diagram <"+diagramPath+"> to file <"+fileName+">: "+GetLastError();
		LOGError(errorMessage);
		return 0;

	}
	CopyFile(fileName, versionFileName);

	// Удаление из описания диаграммы старой информации:
	const DIAGRAM_INFO_TOKEN = "#####";
	// Подготовка и обновление новой информации для диаграммы:
	var diagramInfo = "<b>Export date:</b> " + (new Date()).toLocaleString('ru-RU'); // toLocaleDateString('ru-RU');
	diagramInfo += "\r\n<b>File name:</b> " + GetDiagramImageFileName( theDiagram );
	if (aGitProjectPath) {
		diagramInfo += "\r\n<b>Main Image Git:</b> " + GetDiagramGitImageFileName( aGitProjectPath, theDiagram );
		diagramInfo += "\r\n<b>Version Image Git:</b> " + GetDiagramGitVersionImageFileName( aGitProjectPath, theDiagram );
	}
	if (!ReplaceTextInDiagramNotes( theDiagram.DiagramID, diagramInfo, DIAGRAM_INFO_TOKEN)) {
		Session.Output("ERROR Diagram update <"+diagramPath+">:"+updatableDiagram.GetLastError());
	}
	if (currentDiagramID != theDiagram.DiagramID) {
		// Если была активна другая диаграмма, то обрабатываему диаграмму нужно закрыть, так как она появляется на экране
		Repository.CloseDiagram(theDiagram.DiagramID);
	}

	Session.Output("Diagram <"+diagramPath+"> has been exported to files:");
	Session.Output("   "+fileName);
	Session.Output("   "+versionFileName);
	return 1;
}

// Выгрузка диаграммы в формате PlantUML с учетом вида диаграммы
function exportPlantUMLDiagram(diagram, fileName){
	var backupExtention = null; // ".bak"
	switch (diagram.Type) {
		case "Sequence": 	
			return exportSequenceDiagramToPlantUML(diagram, fileName, backupExtention);
		case "Activity":
			return exportActivityDiagramToPlantUML(diagram, fileName, backupExtention);
		case "Statechart":
		case "Logical":
		case "Class":
		case "Component":
		case "Deployment":
			return exportStructuralDiagramToPlantUML(diagram, fileName, backupExtention);
		case "Use Case":	
			return exportStructuralDiagramToPlantUML(diagram, fileName, backupExtention);
	}
	throw new Error("Code generation for the <" + diagram.Type + "> diagram is not not supported.");
}

// Выгрузка диаграммы в Git с обновлением информации в описании диаграммы
function exportPlantUMLDiagramToGit( aProject, anExportPath, aGitProjectPath, aPackagePath, aDiagram ) {
	var theDiagram as EA.Diagram;
	theDiagram = aDiagram;
	var diagramPath = aPackagePath + " \\ " + theDiagram.Name;

	if (IsDeletedDiagram(theDiagram)) {
		Session.Output( "Diagram is deleted: " + diagramPath );
		return 0;
	}

	var theProject as EA.Project;
	theProject = aProject;
	var fileName = GetDiagramFullPlantUMLFileName( anExportPath, theDiagram );
	var versionFileName = GetDiagramFullVersionPlantUMLFileName( anExportPath, theDiagram );

	var countDiagrams = exportPlantUMLDiagram(theDiagram, fileName);
	if (!countDiagrams) {
		var errorMessage = "Can not export diagram <"+diagramPath+"> to file <"+fileName+">: "+GetLastError();
		LOGError(errorMessage);
		return 0;

	}
	CopyFile(fileName, versionFileName);
    logMessage("Создана копия файла: " + versionFileName, "INFO");
	// Удаление из описания диаграммы старой информации:
	const DIAGRAM_INFO_TOKEN = "=====";

	// Подготовка и обновление новой информации для диаграммы:
	var diagramInfo = "<b>Export date:</b> " + (new Date()).toLocaleString('ru-RU'); // toLocaleDateString('ru-RU');
	diagramInfo += "\r\n<b>File name:</b> " + GetDiagramPlantUMLFileName( theDiagram );
	if (aGitProjectPath) {
		diagramInfo += "\r\n<b>Main PlantUML Git:</b> " + GetDiagramGitPlantUMLFileName( aGitProjectPath, theDiagram );
		diagramInfo += "\r\n<b>Version PlantUML Git:</b> " + GetDiagramGitVersionPlantUMLFileName( aGitProjectPath, theDiagram );
	}

	// Обновить нужно другой инстанс диаграммы, чтобы не слетело форматирование
	if (!ReplaceTextInDiagramNotes( theDiagram.DiagramID, diagramInfo, DIAGRAM_INFO_TOKEN)) {
		Session.Output("ERROR Diagram update <"+diagramPath+">:"+updatableDiagram.GetLastError());
	}

	Session.Output("Diagram <"+diagramPath+"> has been exported to file "+fileName);
	return countDiagrams;
}

