function exportSequenceDiagramToPlantUML(diagram, fileName, backupExtention) {
	if (!existsDirectory(fileName)){
        logMessage("Каталог для файла <"+fileName+"> не существует.", "ERROR");
		return 0;
	};
    var startTime = new Date();
    try {
        logMessage("Начинаем экспорт Sequence диаграммы в PlantUML", "INFO");

        // Валидируем диаграмму
        var validation = validateDiagramForExport(diagram);
        if (validation.errors.length > 0) {
            for (var i = 0; i < validation.errors.length; i++) {
                logMessage(validation.errors[i], "ERROR");
            }
            return;
        }

        for (var i = 0; i < validation.warnings.length; i++) {
            logMessage(validation.warnings[i], "WARNING");
        }

        logMessage("Диаграмма: " + diagram.Name + " (тип: " + diagram.Type + ")", "INFO");

		var plantUMLCode = getPlantUMLSequenceCode(diagram, null);

        // Сохраняем в файл
        saveToFile(plantUMLCode, fileName, backupExtention, "Plantuml (*.puml)|*.puml|All Files (*.*)|*.*||");

        var endTime = new Date();
        var processingTime = (endTime - startTime) / 1000;

        logMessage("Экспорт завершен успешно за " + processingTime + " секунд", "INFO");
        logMessage("Файл сохранен: " + fileName, "INFO");
    } catch (error) {
        logMessage("Ошибка при экспорте: " + error.message, "ERROR");
        logMessage("Стек вызовов: " + error.stack, "ERROR");
		throw error;
    }
	return 1;
}

function getPlantUMLSequenceCode( pDiagram, skippedElementIDList ) {
	var diagram as EA.Diagram;
	diagram = pDiagram;

	if (!diagram.DiagramObjects){
		LOGInfo("Diagram <"+diagram.Name+ "> has not objects.");
		return;
	}

	LOGInfo("Create Sequence PlantUML script activated");
	LOGTrace("diagram.DiagramObjects.Count = "+diagram.DiagramObjects.Count);
	var diagramObject as EA.DiagramObject;
	var element as EA.Element;
	var participantList = [];
	var sequenceList = [];
	var previousSequence = null;
	for( var i = 0; i < diagram.DiagramObjects.Count; i++) {
		diagramObject = diagram.DiagramObjects.GetAt(i);
		element = Repository.GetElementByID(diagramObject.ElementID);
		if (!element){
			LOGTrace("Not found element with ElementID=<"+diagramObject.ElementID+"> (x,y)=("+diagramObject.left + ", " + diagramObject.top + ")");
			continue;
		}
		if (["Component","Class","Actor","Boundary","Sequence","ProvidedInterface","MessageEndpoint"].includes(element.Type)) {
			var parentElement as EA.Element;
			var parentElement = (element.ParentID ? Repository.GetElementByID(element.ParentID) : null);
			var parentElementName = (parentElement ? (parentElement.Name="" ? parentElement.Alias : parentElement.Name) + " " : "");
			var elementName = NameNormalization( parentElementName + (element.Name = "" ? element.Alias : element.Name) );
			LOGTrace(i+". "+element.Type + " [" + element.ElementID + "] - " + NameNormalization(element.Name) + " ParenId = ["+element.ParentID+"], Elements.Count = "+ element.Elements.Count + " diagramObject.BackgroundColor = "+ diagramObject.BackgroundColor + " GetElementColor(element.Type, diagramObject.BackgroundColor)="+ GetElementColor(element.Type, diagramObject.BackgroundColor, null));
			var participant = {
				id: element.ElementID,						// 0
				type: element.Type,							// 1
				name: elementName,							// 2
				// alias: NameNormalization( parentElementName + element.Alias),	// 3
				stereotype: element.Stereotype,				// 4
				left: diagramObject.left,					// 5
				right: diagramObject.right,					// 6
				centre: diagramObject.left + (diagramObject.right - diagramObject.left)/2,	// 9
				color: GetElementColor(element.Type, diagramObject.BackgroundColor, null), // 8 
				parentId: element.ParentID
			};
			participantList.push( participant );
			continue;
		}
		if (((element.Type == "Note") && (element.Name == "PlantUML")) || (skippedElementIDList && skippedElementIDList.includes(element.ElementID))) {
			// Skip PlantUML Note or outputElement
			continue;
		}
		if ((element.Type == "Note") && (element.Name != "PlantUML")) {
			var sequence = {
				top: diagramObject.top * -1, 			// 0
				clientId: 0,							// 1
				supplierId: 0,							// 2
				name: element.Notes, 					// 3
				type: "Note",							// 4
				color: GetElementColor("Note", diagramObject.BackgroundColor, null),// 5
				parameters: 0,							// 5
				left: diagramObject.left,				// 7
				right: diagramObject.right, 			// 8
				activations: [],
			}
			previousSequence = sequence;
			sequenceList.push( sequence );
			continue;
		}
		if (element.Type == "InteractionFragment") {
			//LOGDebug( "Fragment (" + element.ElementID + ") name=" + element.Name + " t=" + diagramObject.top + ", b=" + diagramObject.bottom + ", l=" + diagramObject.left + ", r=" + diagramObject.right + ", Partitions.Count=" + element.Partitions.Count);
			var sequence = {
				top: diagramObject.top * -1,					// 0
				clientId: 0,									// 1
				supplierId: 0,									// 2
				name: element.Name,								// 3
				type: FragmentTypeToString(element.Subtype), 	// 4
				parameters: 0,									// 5
				left: 0,										// 7
				right: 0,										// 8
				activations: [],
			}
			sequenceList.push( sequence );
			if (element.Partitions.Count) {
				var line_offset = (diagramObject.top * -1) + 20;
				for (var j = 0; j < element.Partitions.Count; j++) {
					var partition as EA._Partition;
					partition = element.Partitions.GetAt(j);
					LOGDebug( "Partitition for " + element.ElementID + " " + "name=" + partition.Name + " object type=" + partition.ObjectType + " operator=" + partition.Operator + " size=" + partition.size + " note=" + partition.Note);
					var sequence = {
						top: line_offset,								// 0
						clientId: 0,									// 1
						supplierId: 0,									// 2
						name: partition.Name,							// 3
						type: "Else", 									// 4
						parameters: 0,									// 5
						left: 0,										// 7
						right: 0,										// 8
						activations: [],
					}
					previousSequence = sequence;
					sequenceList.push( sequence );
					line_offset = line_offset + partition.Size;
				}
			}
			// suppress end for dividers
			if (!previousSequence || (previousSequence.type != "divider")) {
				sequence = {
					top: diagramObject.bottom *-1,					// 0
					clientId: 0,									// 1
					supplierId: 0,									// 2
					name: "",										// 3
					type: "End", 									// 4
					parameters: 0,									// 5
					left: 0,										// 7
					right: 0,										// 8
					activations: [],
				}
				sequenceList.push( sequence );
			}
			continue;
		}
		LOGWarning( element.Type + " <" + NameNormalization(element.Name) + "> is not added to PlantUML diagram.")
	};
	// Load DiagramLinks 
	LOGDebug("");
	LOGDebug("***** Load DiagramLinks *****");
	for (var j = 0; j < diagram.DiagramLinks.Count; j++) {
		var diagramLink as EA.DiagramLink;
		var connector as EA.Connector;
		diagramLink = diagram.DiagramLinks.GetAt( j );
		connector = Repository.GetConnectorByID(diagramLink.ConnectorID);
		LOGDebug( j+". Connector (" + connector.ConnectorID + ") " + connector.Name + " #:" + connector.SequenceNo + ", sx:" + connector.StartPointX + ", sy:" + connector.StartPointY + ", ex:" + connector.EndPointX + ", ey: " + connector.EndPointY );
		if ((connector.SequenceNo == 0) || (connector.StartPointX == 0 && connector.StartPointY == 0)) {
			// Skip not visible connectors
			continue;
		}
		var sequence = {
			top: connector.StartPointY * -1,				// 0
			clientId: connector.ClientID,					// 1
			supplierId: connector.SupplierID,				// 2
			name: connector.Name,							// 3
			type: connector.MiscData(0),					// 4 synch or async
			parameters: connector.MiscData(1),				// 5 return value and parameters
			isReturn: (connector.MiscData(3) != "0"),		// 6 isReturn
			left: 0,										// 7
			right: 0,										// 8
			sequenceNo: connector.SequenceNo,
			activations: [],
			newGroupActivation: connector.StateFlags.includes("Initiate=1;"),
		};
		sequenceList.push( sequence );
	};

	if (diagram.SwimlaneDef.Swimlanes.Count > 1) {
		// Property "swimlane.Width" does not work correctly, so make SQL query:
		var sql = "SELECT x.requirement as requirement, x.Partition as partition, x.Name as name\
			FROM t_diagram d \
				INNER JOIN t_xref x ON x.client = d.ea_guid AND x.type = 'swimlane' \
			WHERE d.ea_guid = '" + diagram.DiagramGUID + "' \
			ORDER BY x.Partition";
		var sqlResult = Repository.SQLQuery( sql );
		LOGTrace("swimlaneWidth:");
		LOGTrace(sqlResult);
		var swimlaneWidthList = sqlResult.match(/[>,;]SW=(\d*);/gm);
		var swimlaneWidth = 0;
		for (var s = 0; s < diagram.SwimlaneDef.Swimlanes.Count; s++) {
			var swimlane = diagram.SwimlaneDef.Swimlanes.Items(s);
			var sequence = {
				top: swimlaneWidth,								// 0
				clientId: 0,									// 1
				supplierId: 0,									// 2
				name: swimlane.Title,							// 3
				type: "swimlane",								// 4 synch or async
				parameters: "",									// 5 return value and parameters
				isReturn: false,								// 6 isReturn
				left: 0,										// 7
				right: 0,										// 8
				sequenceNo: 0,
				activations: [],
			};
			LOGTrace( "****** Swimlane <" + swimlane.Title + "> (" + swimlaneWidth + ")");
			if (s > 0) {
				// Start from second swimlane because header is not included in the PlantUML
				sequenceList.push( sequence );
			}
			if (swimlaneWidthList && (s < swimlaneWidthList.length)) {
				var value = swimlaneWidthList[s].slice(4);
				swimlaneWidth += parseInt(value);
			}
		}
	}
	var visibleParticipantList = participantList.filter(p => sequenceList.some(s => {return (p.id == s.clientId || p.id == s.supplierId)}));
	var sortedParticipantList = visibleParticipantList.sort((a,b) => {return (a.left - b.left)});
	// LOGTrace( "sequenceList.length = " + sequenceList.length );
	var sortedSequenceList = sequenceList.sort((a,b) => {return (a.top - b.top)});
	// LOGTrace( "************************* sortedParticipantList.length = " + sortedParticipantList.length );
	// PrintArray(sortedParticipantList);
	//LOGTrace( "************************* sortedSequenceList.length = " + sortedParticipantList.length );
	//PrintArray(sortedSequenceList);
	// PrintArray(sequenceList);
	//

	// Activate and Deactivate
	// Перебираем до предпоследнего элемента
	LOGTrace("");
	LOGTrace("****** Activate and Deactivate ");
	var linkedSequenceList = sortedSequenceList.filter(i => i.supplierId && i.clientId);
		function PushDistinctValue( pSequence, pValue) {
			var list = pSequence.activations;
			if (!list.some(i => i === pValue)) {
				list.push(pValue);
			}
//			LOGTrace("* " + pSequence.name + " (" + pSequence.top + "): " + pValue);
		}
	for(var i = 0; i < linkedSequenceList.length; i++){
		var currentSequence = linkedSequenceList[i];
		var isCycleLink = currentSequence.clientId == currentSequence.supplierId;
		var nextSequence = (i < (linkedSequenceList.length + 1) ? linkedSequenceList[i+1] : null);
		var previousSequence = (i > 0 ? linkedSequenceList[i-1] : null);
		var client = participantList.find(p => p.id == currentSequence.clientId);
		var supplier = participantList.find(p => p.id == currentSequence.supplierId);
		if (!nextSequence) {
			// Последняя на диаграмме ссылка
			PushDistinctValue( currentSequence, "deactivate "+ client.name );
			PushDistinctValue( currentSequence, "deactivate "+ supplier.name );
		}
		LOGTrace("****** " + currentSequence.name + " (" + currentSequence.top + ") - " + (nextSequence ? nextSequence.name : "нет следующей связи" )+ ": " + currentSequence.supplierId + " = " + (nextSequence ? nextSequence.clientId : "null"));
		// Проверяем, что нужно начать линию у Client
		var clientBeforeClient = linkedSequenceList.filter(i => (i.clientId == currentSequence.clientId) && (i.top < currentSequence.top)).slice(-1)[0];
		var activateClient = false;
		if (nextSequence && !currentSequence.isReturn && !(clientBeforeClient && !clientBeforeClient.isReturn)&& !(previousSequence && previousSequence.supplierId == currentSequence.clientId)) {
			// Нет предыдущей линии, которая начала timeline и текущая связь не продолжение предыдущей
			PushDistinctValue( currentSequence, "activate "+ client.name );
			activateClient = true;
		}
		if (nextSequence && currentSequence.newGroupActivation && clientBeforeClient) {
			PushDistinctValue( clientBeforeClient, "deactivate "+ client.name );
			PushDistinctValue( currentSequence, "activate "+ client.name );
			activateClient = true;
		}
		// Есть проблема с отображением: нужно явно делать deactivate
		var existsAfterClient =  linkedSequenceList.some(i => (i.clientId == currentSequence.clientId || i.supplierId == currentSequence.clientId) && (i.top > currentSequence.top));
		if (!existsAfterClient && !activateClient) {
			PushDistinctValue( currentSequence, "deactivate "+ client.name );
		}
		// Проверяем, что нужно начать линию у Supplier
		if (nextSequence && (currentSequence.supplierId == nextSequence.clientId) && !currentSequence.isReturn) {
			if (!isCycleLink) {
				// Не циклическая связь
				PushDistinctValue( currentSequence, "activate "+ supplier.name );
			}
		}
		// Проверяем, что нужно прервать линию у previousSequence
		if (previousSequence) {
			var supplierAfterPreviousClient = linkedSequenceList.filter(i => (i.supplierId == previousSequence.clientId) && (i.top > previousSequence.top))[0];
			if ((previousSequence.supplierId != currentSequence.clientId) && 
				!(supplierAfterPreviousClient && supplierAfterPreviousClient.isReturn) && 
				!(supplierAfterPreviousClient && (supplierAfterPreviousClient.clientId == supplierAfterPreviousClient.supplierId))
				) {
				// Текущая линия не продолжение предыдущей и нет возвратной стрелки и предыдущая линия не циклическая связь
				var previousSupplier = participantList.find(p => p.id == previousSequence.supplierId);
				PushDistinctValue( previousSequence, "deactivate "+ previousSupplier.name );
			}
		}
		// Проверяем, что нужно где-то прервать линию client
		var nearestBeforeSupplier = linkedSequenceList.filter(i => (i.clientId == currentSequence.supplierId || i.supplierId == currentSequence.supplierId) && (i.top < currentSequence.top)).slice(-1)[0];
		//var nearestClientBeforeSupplier = linkedSequenceList.filter(i => (i.clientId == currentSequence.supplierId) && (i.top < currentSequence.top)).slice(-1)[0];
		if (nearestBeforeSupplier && previousSequence && !currentSequence.isReturn){
			if (!isCycleLink) {
				PushDistinctValue( nearestBeforeSupplier, "deactivate "+ supplier.name );
			}
			if ((previousSequence.clientId != currentSequence.clientId) && (previousSequence.supplierId != currentSequence.clientId)) {
				// Текущая связь не является следующим шагом и не предшествующая последовательность вызовов
				var previousClient = participantList.find(p => p.id == previousSequence.clientId);
				if (previousClient) {
//					PushDistinctValue( previousSequence, "deactivate "+ previousClient.name );
				}
			}
			if (previousSequence.supplierId != currentSequence.clientId) {
				// Текущая связь не является следующим вызовом
				var previousSupplier = participantList.find(p => p.id == previousSequence.supplierId);
				if (previousSupplier) {
					PushDistinctValue( previousSequence, "deactivate "+ previousSupplier.name );
				}
			}
		}
		var nearestBeforeClient = linkedSequenceList.filter(i => (i.clientId == currentSequence.clientId || i.supplierId == currentSequence.clientId) && (i.top < currentSequence.top)).slice(-1)[0];
		if (nearestBeforeClient && previousSequence && !currentSequence.isReturn){
			if (!isCycleLink && nearestBeforeClient.isReturn && nearestBeforeClient.clientId == currentSequence.clientId) {
				// Если предыдущая связь была возвратом, а текущая не возврат
				PushDistinctValue( nearestBeforeClient, "deactivate "+ client.name );
			}
		}
	}// for
	// Generating PlantUML:
	var generated_script = "@startuml"+"\r\n";
	// Manual activation
	generated_script += "autoactivate off"+"\r\n";
	generated_script += "autonumber"+"\r\n";
	generated_script += "skinparam linetype polyline"+"\r\n";
	generated_script += "skinparam linetype ortho"+"\r\n";
	generated_script += "title " + diagram.Name + "\r\n";
	//generated_script += "!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Sequence.puml\r\n";
	generated_script += "!include <logos/flask.puml>\r\n";
	generated_script += "!include <logos/kafka.puml>\r\n";
	generated_script += "!include <logos/kotlin.puml>\r\n";
	generated_script += "!include <logos/cassandra.puml>\r\n";
	var box_right = 0;
	sortedParticipantList.forEach(function( participant ){
		if (participant.name == "") {
			return;
		}
		if (participant.type == "Boundary") {
			// Found the Start of the Box
			generated_script += "Box " + participant.name + (participant.color ? " " + participant.color : "") + "\r\n";
			box_right = participant.right;
		} else {
			if (box_right > 0) {
				if (participant.left > box_right) {
					// Found the End of the Box
					generated_script += "End Box \r\n";
					box_right = 0;
				}
			}
			generated_script += ParticipantToName(participant.type, participant.stereotype) + " " + participant.name + (participant.color ? " " + participant.color : "") + "\r\n";
		}
	});
	if (box_right > 0) {
		// Found the End of the Box
		generated_script += "End Box \r\n";
		box_right = 0;
	}

	sortedSequenceList.forEach(function(sequence){
		var strLine = "";
		if (sequence.type == "Note") {
//			strLine = "note " + resolveNoteLocation(sequence, sortedParticipantList) + " " + GetElementColor("Note", sequence.color, null) + "\r\n\t" + WrapText(sequence.name) + "\r\n" + "end note";
			strLine = "note " + resolveNoteLocation(sequence, sortedParticipantList) + " " + sequence.color + "\r\n\t" + WrapText(sequence.name) + "\r\n" + "end note";
		} else if (sequence.type == "swimlane" || sequence.type == "divider"){
			strLine = "== " + sequence.name + " ==";
		} else if (!sequence.clientId) {
			strLine = sequence.type + " " + sequence.name;
		} else {
			var client = participantList.find(p => p.id == sequence.clientId);
			var supplier = participantList.find(p => p.id == sequence.supplierId);
			strLine += (client ? client.name : "UndefinedClient") + SequenceArrow(sequence.type, sequence.isReturn) + (supplier ? supplier.name : "UndefinedSupplier");
			if (sequence.name.length) {
				strLine += ": " + (sequence.name.includes("(") ? sequence.name : FormatSequenceParameters(sequence.name , sequence.parameters));
			}
			strLine += "\r\n" + sequence.activations.join("\r\n");
		}
		generated_script += strLine + "\r\n";
	});

	generated_script += "@enduml";
	return generated_script;
}

!INC Local Scripts.EAConstants-JavaScript
!INC EAScriptLib.JavaScript-Logging

/*
 * Script Name: Diagram Scripts.Export attributes
 * Author: Sergey Gaidamakov
 * Purpose: Load JSON structures from Swagger into Class elements.
 * Date: 03.01.2024
 *
 */

// LOGLEVEL = LOGLEVEL_ERROR;
// LOGLEVEL = LOGLEVEL_INFO;
// LOGLEVEL = LOGLEVEL_WARNING;
// LOGLEVEL = LOGLEVEL_DEBUG;
LOGLEVEL = LOGLEVEL_TRACE;

function OnDiagramScript()
{
	// Show the script output window
	Repository.EnsureOutputVisible( "Script" );
	Repository.ClearOutput("Script");

	// Get a reference to the current diagram
	var currentDiagram as EA.Diagram;
	currentDiagram = Repository.GetCurrentDiagram();

	if ( currentDiagram == null ){
		Session.Prompt( "This script requires a diagram to be visible.", promptOK);
		return;
	}
	// Get a reference to any selected connector/objects
	var selectedConnector as EA.Connector;
	var selectedObjects as EA.Collection;
	selectedConnector = currentDiagram.SelectedConnector;
	selectedObjects = currentDiagram.SelectedObjects;
	if ( selectedObjects.Count != 1 )
	{
		if (selectedObjects.Count == 0) {
			Session.Prompt("Select a Class element to load attributes." , promptOK);
		} else {
			Session.Prompt("Select any one Class element to load attributes." , promptOK);
		}
		return;
	}
	var selectedObject as EA.DiagramObject;
	var selectedObject = selectedObjects.GetAt(0);
	var theSelectedElement as EA.Element;
	var theSelectedElement = Repository.GetElementByID(selectedObject.ElementID);
	if (!theSelectedElement || theSelectedElement.ObjectType != otElement || theSelectedElement.Type != "Class") {
		Session.Prompt( "Select a Class element to load attributes." , promptOK);
	}
	var jsonString = Session.Input("Enter JSON string without NEWLINE:");
	if (!jsonString) {
		return;
	}
	//var jsonString = '{"a": "string", "b": "int", "c": "datetime", "myObject": {"param1": "string", "param2": "int"}}';
	LOGTrace("JSON = " + jsonString);
	var json = JSON.parse(jsonString);
	AppendAttributes(theSelectedElement, json);
}

function AppendAttributes( pClass, jsonAttributes ){
	// The method theClass.Attributes.GetByName() do not work, so we need to do cycle:
	function FindAttributeInClass( aClass, attributeName){
		var theClass as EA.Element;
		theClass = aClass;
		for (var i=0; i < theClass.Attributes.Count; i++){
			var attribute as EA.Attribute;
			attribute = theClass.Attributes.GetAt(i);
			if (attribute.Name == attributeName){
				return attribute;
			}
		}
		return null;
	}
	var currentDiagram as EA.Diagram;
	currentDiagram = Repository.GetCurrentDiagram();
	var theClass as EA.Element;
	theClass = pClass;
	LOGTrace("**** AppendAttributes ("+theClass.Name+")");
	for (var key in jsonAttributes) {
		if (!jsonAttributes.hasOwnProperty(key)){
			LOGTrace("Attribute <" + key + "> is not own property.");
			continue;
		}

		var foundAttribute as EA.Attribute;
		foundAttribute = FindAttributeInClass( theClass, key);
		if (foundAttribute) {
			LOGTrace("Attribute <" + key + "> exists in the Class <"+theClass.Name+">");
			continue;
		}

		// Default attribute type
		var attributeType = jsonAttributes[key];
		var attributeClassifierID = null;
		var isObjectProperty = typeof(jsonAttributes[key])=="object";
		var isArrayProperty = Array.isArray(jsonAttributes[key]);
		if (isArrayProperty){
			// Нужно проверить вложенный тип
			if (typeof(jsonAttributes[key][0])=="object"){
				// Сложный тип, нужно создавать объект
				LOGTrace("Attribute name <" + key + "> is ARRAY property of complex type.");
			} else {
				// Простой тип, объект создавать не нужно
				isObjectProperty = false;
				attributeType = jsonAttributes[key][0];
				LOGTrace("Attribute name <" + key + "> is ARRAY property of simple type <"+attributeType +">.");
			}
		} else if (isObjectProperty){
			LOGTrace("Attribute name <" + key + "> is OBJECT property.");
		}

		if (isObjectProperty) {
			if (!jsonAttributes.propertyIsEnumerable(key)){
				LOGTrace("Attribute name <" + key + "> is OBJECT not enumeratable property.");
				continue;
			}
			if (isArrayProperty){
				// Нужно проверить вложенный тип
				if (typeof(jsonAttributes[key][0])=="object"){
					// Сложный тип, нужно создавать объект
					LOGTrace("Attribute name <" + key + "> is ARRAY property of complex type.");
				} else {
					// Простой тип, объект создавать не нужно
					LOGTrace("Attribute name <" + key + "> is ARRAY property of simple type.");
				}
			} else {
				LOGTrace("Attribute name <" + key + "> is OBJECT property.");
			}
			attributeType = "Object_" + key;
			var newElement as EA.Element;
			newElement = currentDiagram.GetElementByName(attributeType);
			if (!newElement || newElement.ObjectType != otElement || newElement.Type != "Class") {
				LOGTrace("Class name <" + attributeType  + "> is not found on diagram.");
				var aPackage as EA.Package;
				aPackage = Repository.GetPackageByID(currentDiagram.PackageID);
				if (!aPackage){
					Session.Prompt( "A package for diagram <"+currentDiagram.Name+"> not found" , promptOK);
					return;
				}
				//
				newElement = aPackage.Elements.GetByName(attributeType);
				if (!newElement || newElement.ObjectType != otElement || newElement.Type != "Class") {
					LOGTrace("Class name <" + key + "> is not found in the package.");
					// New Class element
					newElement = aPackage.Elements.AddNew(attributeType,"Class");
					if (!newElement.Update()) {
						Session.Prompt( "An error of creating element in package:"+newElement.GetLastError(), promptOK);
						return;
					}
					// Connector
					var connector as EA.Connector;
					connector = newElement.Connectors.AddNew("","Aggregation");
					connector.SupplierID = theClass.ElementID;
					connector.SupplierEnd.Aggregation = 2; // composite;
					if (isArrayProperty){
						connector.ClientEnd.Cardinality = "0..*";
					}
					connector.ClientEnd.Role = key;
					if (!connector.Update()){
						Session.Prompt( "An error of adding connector to elements:"+connector.GetLastError(), promptOK);
						return;
					}
				}
				attributeClassifierID = newElement.ElementID;
				// Add to Diagram
				var diagramObject as EA.DiagramObject;
//				diagramObject = currentDiagram.DiagramObjects.AddNew("l=200;r=400;t=200;b=200;","Class");
				diagramObject = currentDiagram.DiagramObjects.AddNew("l=200;t=200","");
				diagramObject.ElementID = newElement.ElementID;
				if (!diagramObject.Update()) {
					Session.Prompt( "An error of adding element to diagram:"+diagramObject.GetLastError(), promptOK);
					return;
				}
				currentDiagram.DiagramObjects.Refresh();
				//
				var diagramNumber = currentDiagram.DiagramID;
				Repository.CloseDiagram(diagramNumber);
				Repository.OpenDiagram(diagramNumber);
			}
			if (isArrayProperty){
				AppendAttributes( newElement, jsonAttributes[key][0] );
			} else {
				AppendAttributes( newElement, jsonAttributes[key] );
			}
		}

		LOGTrace("Attribute name <" + key + "> : "+attributeType);
		var newAttribute as EA.Attribute;
		newAttribute = theClass.Attributes.AddNew(key, attributeType);
		if (attributeClassifierID) {
			newAttribute.ClassifierID = attributeClassifierID;
		}
		if (isArrayProperty) {
			newAttribute.IsCollection = true;
			newAttribute.LowerBound = "0";
			newAttribute.UpperBound = "*";
		}
		newAttribute.Update();
	}
	theClass.AttributesEx.Refresh();
}

// {"a": "string", "b": "int", "c": "datetime"}
OnDiagramScript();

