/*
 *
 * Script Name: Diagram Scripts.Export attributes
 * Author: Sergey Gaidamakov
 * Purpose: Выгрузка диаграммы в виде PlantUML скрипта.
 * Date: 16.09.2023
 *
 */

// LOGLEVEL = LOGLEVEL_ERROR;
// LOGLEVEL = LOGLEVEL_INFO;
// LOGLEVEL = LOGLEVEL_WARNING;
// LOGLEVEL = LOGLEVEL_DEBUG;
LOGLEVEL = LOGLEVEL_TRACE;

function OnDiagramScript()
{
	// Show the script output window
	Repository.EnsureOutputVisible( "Script" );
	Repository.ClearOutput("Script");

	// Get a reference to the current diagram
	var currentDiagram as EA.Diagram;
	currentDiagram = Repository.GetCurrentDiagram();

	if ( !currentDiagram ){
		Session.Prompt( "This script requires a diagram to be visible.", promptOK);
		return;
	}
	try {
		var fileName = getFileNameForDiagram(currentDiagram);
		if (!fileName) {
			return;
		}
		logMessage("Файл диаграммы "+fileName,"INFO");
		Repository.SaveDiagram(currentDiagram.DiagramID);
		exportPlantUMLDiagram(currentDiagram, fileName);
		// Перезагружаем диаграмму, чтобы загрузилось описание в свойства диаграммы
		Repository.ReloadDiagram(currentDiagram.DiagramID);

		LOGInfo( "Script completed successfull" );
		Session.Prompt("The PlantUML code has been successfully exported to file " + fileName + ".", promptOK);
    } catch (error) {
		LOGError( "Script completed with error:" + error.message );
		Session.Prompt("ERROR! The PlantUML code has not been exported. "+ error.message, promptOK);
	}
}

