/*
 * Script Name: Diagram Scripts.Load attributes
 * Author: Sergey Gaidamakov
 * Purpose: Copy attributes from one class to other class.
 * Date: 01/01/2024
 *
 */

// LOGLEVEL = LOGLEVEL_ERROR;
// LOGLEVEL = LOGLEVEL_INFO;
// LOGLEVEL = LOGLEVEL_WARNING;
// LOGLEVEL = LOGLEVEL_DEBUG;
LOGLEVEL = LOGLEVEL_TRACE;

function OnItemScript()
{
	function AppropriatedElement( aElement ){
		var theElement as EA.Element;
		theElement = aElement;
		if (!theElement || theElement.ObjectType != otElement || (theElement.Type != "Class" && theElement.Type != "Component")){
			return false;
		}
		return true;
	}
	// Show the script output window
	// Repository.EnsureOutputVisible( "Script" );
	Repository.ClearOutput("Script");

	// Get a reference to the current diagram
	var currentDiagram as EA.Diagram;
	currentDiagram = Repository.GetCurrentDiagram();
	if ( currentDiagram == null ){
		Session.Prompt( "This script requires a diagram to be visible.", promptOK);
		return;
	}

	// Get a reference to any selected connector/objects
	var selectedObjects as EA.Collection;
	selectedObjects = currentDiagram.SelectedObjects;
	var theSelectedSourceElement as EA.Element;
	var theSelectedDestinationElement as EA.Element;
	if ( selectedObjects.Count == 1 ) {
		var selectedDestinationObject as EA.DiagramObject;
		selectedDestinationObject = selectedObjects.GetAt(0);
		theSelectedDestinationElement = Repository.GetElementByID(selectedDestinationObject.ElementID);

		var result = Repository.InvokeConstructPicker("IncludedTypes=Class,Component");
		theSelectedSourceElement = Repository.GetElementByID(result);
	} else if ( selectedObjects.Count == 2 ) {
		var selectedDestinationObject as EA.DiagramObject;
		selectedDestinationObject = selectedObjects.GetAt(0);
		theSelectedDestinationElement = Repository.GetElementByID(selectedDestinationObject.ElementID);

		var selectedSourceObject as EA.DiagramObject;
		selectedSourceObject = selectedObjects.GetAt(1);
		theSelectedSourceElement = Repository.GetElementByID(selectedSourceObject.ElementID);
	} else {
		Session.Prompt("Select 2 item to copy attributes." , promptOK);
		return;
	}

	if (!AppropriatedElement(theSelectedSourceElement)){
		Session.Prompt( "Select source a Class or Component element to copy attributes." , promptOK);
	}
	if (!AppropriatedElement(theSelectedDestinationElement)){
		Session.Prompt( "Select destination a Class or Component element to copy attributes." , promptOK);
	}
	var result = Session.Prompt("Copy attributes from <"+theSelectedSourceElement.Name+"> to <"+theSelectedDestinationElement.Name+">" , promptYESNO);
	if (result != resultYes) {
		return;
	}
	CopyAttributes(theSelectedSourceElement, theSelectedDestinationElement);
}

// Выгрузка атрибутов указанного класса
function CopyAttributes( aSourceElement, aDestinationElement ){
	function FindAttributeInDestination( anElement, attributeName){
		var theElement as EA.Element;
		theElement = anElement;
		for (var i=0; i < theElement.Attributes.Count; i++){
			var attribute as EA.Attribute;
			attribute = theElement.Attributes.GetAt(i);
			if (attribute.Name == attributeName){
				return attribute;
			}
		}
		return null;
	}
	var theSourceElement as EA.Element;
	var theDestinationElement as EA.Element;
	theSourceElement = aSourceElement;
	theDestinationElement = aDestinationElement;
	for (var i=0; i < theSourceElement.Attributes.Count; i++){
		var attribute as EA.Attribute;
		attribute = theSourceElement.Attributes.GetAt(i);
		var foundAttribute as EA.Attribute;
		foundAttribute = FindAttributeInDestination( theDestinationElement, attribute.Name);
		if (foundAttribute) {
			LOGTrace("Attribute <" + attribute.Name + ": "+attribute.Type+"> exists in the Element <"+theDestinationElement.Name+"> ("+foundAttribute.Name+": "+foundAttribute.Type+")");
			continue;
		}
		LOGTrace("New attribute <" + attribute.Name + ": "+attribute.Type+">");
		var newAttribute as EA.Attribute;
		newAttribute = theDestinationElement.Attributes.AddNew(attribute.Name, attribute.Type);
		newAttribute.Alias = attribute.Alias;
		newAttribute.Notes = attribute.Notes;
		newAttribute.IsCollection = attribute.IsCollection;
		newAttribute.IsConst = attribute.IsConst;
		newAttribute.Stereotype = attribute.Stereotype;
		newAttribute.LowerBound = attribute.LowerBound;
		newAttribute.UpperBound = attribute.UpperBound;
		newAttribute.Update();
	}
	theDestinationElement.AttributesEx.Refresh();
}

OnItemScript();

