/*
 * Script Name: ExportDiagrams.ExportDiagrams-Helper
 * Author: Sergey Gaidamakov
 * Purpose: Вспомогательные функции для выгрузки атрибутов.
 * Date: 08.05.2025
 */

// Выгрузка атрибутов элементов для диаграммы
function ExportAttributesForPackage( pPackage ){
	if ( pPackage == null ){
		Session.Prompt( "This script requires a selected package.", promptOK);
		return;
	}
	var count = 0;
	var theElement as EA.Element;
	var thePackage as EA.Package;
	thePackage = pPackage;
	for (var i=0; i < thePackage.Elements.Count; i++){
		theElement = thePackage.Elements.GetAt(i);
		count = count + ExportAttributes(theElement);
	}
	return count;
}

// Выгрузка атрибутов элементов для диаграммы
function ExportAttributesForDiagram( pDiagram ){
	if ( pDiagram == null ){
		Session.Prompt( "This script requires a selected diagram.", promptOK);
		return;
	}
	var count = 0;
	var theDiagram as EA.Diagram;
	theDiagram = pDiagram;
	if ( theDiagram.DiagramObjects.Count == 0 )
	{
		Session.Prompt("Selected Diagram <"+theDiagram.Name +"> has not elements to export attributes." , promptOK);
		return;
	}
	var diagramObject as EA.DiagramObject;
	var theElement as EA.Element;
	for (var i=0; i < theDiagram.DiagramObjects.Count; i++){
		diagramObject = theDiagram.DiagramObjects.GetAt(i);
		theElement = Repository.GetElementByID(diagramObject.ElementID);
		count = count + ExportAttributes(theElement);
	}
	return count;
}

// Выгрузка атрибутов указанного класса
function ExportAttributes( pElement ){
	if (!pElement){
		return 0;
	}
	var theElement as EA.Element;
	theElement = pElement;
	if (!["Component","Class","ProvidedInterface","Enumeration"].includes(theElement.Type)) {
		return 0;
	}
	const ELEMENT_NAMES = [
		{ type: "Component", name: "Компонент" },
		{ type: "Class", name: "Класс" },
		{ type: "ProvidedInterface", name: "Интерфейс" },
		{ type: "Enumeration", name: "Перечисление" },
	];
	const name = ELEMENT_NAMES.find(i => i.type == theElement.Type).name;
	var description = theElement.Name + ( theElement.Notes ? " (" + theElement.Notes + ")" : "");
	Session.Output(name + " " + description + ":");
	PrintHeaderList();
	for (var i=0; i < theElement.Attributes.Count; i++){
		PrintAttributeList(i+1, theElement.Attributes.GetAt(i));
	}
	PrintFooter();
	return 1;
}

function PrintHeaderHtml(){
	Session.Output("<tr>");
	Session.Output("<td>"+"Name"+"</td><td>"+"Type"+"</td><td>"+"Alias"+"</td><td>"+"Notes"+"</td>");
//	Session.Output("|"+"Name"+"|"+"Type"+"|"+"Alias"+"|"+"Notes"+"|");
	Session.Output("</tr>");
}

function PrintAttributeHtml( pAttribute){
	var attribute as EA.Attribute;
	attribute = pAttribute;
	Session.Output("<tr>");
	Session.Output("<td>"+attribute.Name +"</td><td>"+attribute.Type+"</td><td>"+attribute.Alias+"</td><td>"+attribute.Notes+"</td>");
//		Session.Output("|"+attribute.Name +"|"+attribute.Type+"|"+attribute.Alias+"|"+attribute.Notes+"|");
	Session.Output("</tr>");
}

function PrintHeaderList(){
}

function PrintFooter(){
	Session.Output(" ");
}

function PrintAttributeList( index, pAttribute ){
	var attribute as EA.Attribute;
	attribute = pAttribute;
	var description = [(attribute.Stereotype ? ""+attribute.Stereotype : null), attribute.Alias, attribute.Notes].filter(i => i).map(i => (i.trim().slice(-1) != "." ? i.trim()+"." : i)).join(" ");
	var stringType = attribute.Type;
	if (attribute.LowerBound != "1" || attribute.UpperBound != "1") {
		stringType = attribute.Type + "[" + attribute.LowerBound + ".." + attribute.UpperBound + "]";
	}
	Session.Output(index + ". " + attribute.Name +": " + stringType + (description ? " (" + description + ")": ""));
}

