/*
 * Script Name: Browser Scripts.Export Diagrams
 * Author: Sergey Gaidamakov
 * Purpose: Выгрузка картинок выбранной диаграммы или диаграмм выбранного пакета в каталог
 * Date: 03.01.2024
 *
 */

// LOGLEVEL = LOGLEVEL_ERROR;
// LOGLEVEL = LOGLEVEL_INFO;
// LOGLEVEL = LOGLEVEL_WARNING;
// LOGLEVEL = LOGLEVEL_DEBUG;
LOGLEVEL = LOGLEVEL_TRACE;

function OnProjectBrowserScript()
{
	Repository.EnsureOutputVisible( "Script" );
	Repository.ClearOutput("Script");

	Session.Output( "Session.UserName = " + Session.UserName);

	var exportPath = GetPropertyTypeValue( GetUserExportPathPropertyName() );
	if (!exportPath) {
		// Если не нашли путь, специфичный для текущего пользователя, то берем путь по умолчанию.
		exportPath = GetPropertyTypeValue( GetDefaultExportPathPropertyName() );
		LOGTrace("exportPath from <"+GetDefaultExportPathPropertyName() + "> = " + exportPath);
	}
	if (!exportPath) {
		Session.Prompt( "Not found 'Tagged value type' with name <"+GetDefaultExportPathPropertyName()+">. Define tagged value <"+GetDefaultExportPathPropertyName()+"> at menu 'Settings \\ Reference Data \\ UML Types'", promptOK );
		return;
	}
	var result = Session.Prompt("Export diagrams to path '"+exportPath+"'" , promptYESNO);
	if (result != resultYes) {
		exportPath = Session.Input("Enter export diagrams path");
		if (!exportPath) {
			return;
		}
		// Сохраняем новое значение пути
		SetPropertyTypeValue( GetUserExportPathPropertyName(), exportPath, "Путь для экспорта диаграмм" );
		LOGTrace("exportPath saved to <"+GetUserExportPathPropertyName() + "> = " + exportPath);
	}
	Session.Output("exportPath = " + exportPath);

	// gitProjectPath для данной функции может не задано.
	var gitProjectPath = GetPropertyTypeValue( GetUserGitProjectPropertyName() );
	if (gitProjectPath) {
		Session.Output("gitProjectPath = " + gitProjectPath);
	}
	Session.Output( " " );

	// Get the type of element selected in the Project Browser
	var treeSelectedType = Repository.GetTreeSelectedItemType();
	var myProject as EA.Project;
	myProject = Repository.GetProjectInterface();
	var countDiagrams = 0;

	switch ( treeSelectedType )
	{
		case otElement :
		{
			var theElement as EA.Element;
			theElement = Repository.GetTreeSelectedObject();
			countDiagrams = exportDiagramsFromElement(myProject, exportPath, gitProjectPath, theElement);
			break;
		}
		case otPackage :
		{
			var thePackage as EA.Package;
			thePackage = Repository.GetTreeSelectedObject();
			countDiagrams = exportDiagramsFromElement(myProject, exportPath, gitProjectPath, thePackage);
			break;
		}
		case otDiagram :
		{
			var theDiagram as EA.Diagram;
			theDiagram = Repository.GetTreeSelectedObject();
			var diagramPath = "";
			var theElement as EA.Element;
			theElement = Repository.GetElementByID( theDiagram.ParentID );
			if (theElement) {
				diagramPath = GetElementPath( theElement );
			} else {
				var thePackage as EA.Package;
				var thePackage = Repository.GetPackageByID(theDiagram.PackageID);
				diagramPath = GetElementPath( thePackage );
			}
			countDiagrams = exportDiagramToGit(myProject, exportPath, gitProjectPath, diagramPath, theDiagram.DiagramID);
			break;
		}
		default:
		{
			// Error message
			Session.Prompt( "Select a Package or Diagram to export diagrams.", promptOK );
			return;
		}
	}
	Session.Prompt( countDiagrams + " diagrams has been exported.", promptOK );
}

OnProjectBrowserScript();

