/**
 * Утилиты для работы с диаграммами Sparx Enterprise Architect
 * Версия: 1.0.0
 *
 * Документация:
 * https://sparxsystems.com/enterprise_architect_user_guide/17.1/add-ins___scripting/element.html
 *
 */

/**
 * Получает все элементы диаграммы с учетом вложенности
 */
var _allDiagramElements = null;
var _allDiagramElementsGUID = null;
function getAllDiagramElementsAndObjects(pDiagram, maxDepth) {
	var diagram as EA.Diagram;
	diagram = pDiagram;

	if (_allDiagramElementsGUID) {
		if (diagram.DiagramGUID == _allDiagramElementsGUID) {
			return _allDiagramElements;
		}
		_allDiagramElementsGUID = null;
		_allDiagramElements = null;
	}
	logMessage("Загрузка всех элементов диаграммы", "INFO");

    var diagramElements = new Array();
	var diargamObjList = diagram.DiagramObjects;
	for (var i = 0; i < diargamObjList.Count; i++) {
		var diagramObj as EA.DiagramObject;
		diagramObj = diargamObjList.GetAt(i);
        if (!diagramObj) continue;

		element = Repository.GetElementByID(diagramObj.ElementID);
        if (!element) continue;

		var diagramElement = getDiagramElement(diagramObj, element);
        diagramElements.push(diagramElement);
		logMessage( "Найден " + diagramElement.Name + " <" + diagramElement.Type + ">  id=" + diagramElement.ElementID + " sequence=" + diagramElement.Sequence, "TRACE");
	}

	logMessage("Загрузка элементов диаграммы завершена", "INFO");

	_allDiagramElementsGUID = diagram.DiagramGUID;
	_allDiagramElements = diagramElements;
    return diagramElements;
}

function getDiagramElement( aDiagramObject, anElement){
	var diagramObject as EA.DiagramObject;
	var element as EA.Element;
	diagramObject = aDiagramObject;
	element = anElement;
	return {
		ElementID: element.ElementID,
		Type: element.Type,
		Stereotype: element.Stereotype,
		Subtype: element.Subtype,
		PackageID: element.PackageID,
		ParentID: element.ParentID,
		Name: element.Name,
		Alias: element.Alias,
		Notes: element.Notes,
		ClassfierID: element.ClassfierID,
		ClassifierName: element.ClassifierName,
		ClassifierType: element.ClassifierType,
		ObjectType: element.ObjectType,
		BackgroundColor: diagramObject.BackgroundColor,
		BorderColor: diagramObject.BorderColor,
		FontColor: diagramObject.FontColor,
		Sequence: diagramObject.Sequence,
		bottom: diagramObject.bottom,
		left: diagramObject.left,
		right: diagramObject.right,
		top: diagramObject.top,
		Ports: element.Ports,
		Attributes: element.Attributes,
		Connectors: element.Connectors,
		Constraints: element.Constraints,
		Methods: element.Methods,
		Operations: element.Operations,
		TaggedValues: element.TaggedValues,
		Properties: element.Properties,
		CustomProperties: element.CustomProperties,
		StateTransitions: element.StateTransitions,
	};
}

// Вывод информации об элементе
// detail = 0 - полная информация
// detail = 1 - основные свойства
function logDiagramElement(diagramElement, detail) {
	var margin = "   ";
	if (detail && detail >= 1) {
		logMessage(margin + "**********", "TRACE");
		// Основные свойства элемента
		logMessage(margin + "Name: " + diagramElement.Name, "TRACE");
		logMessage(margin + "ElementID: " + diagramElement.ElementID, "TRACE");
		logMessage(margin + "Type: " + diagramElement.Type, "TRACE");
		logMessage(margin + "Subtype: " + diagramElement.Subtype, "TRACE");
		logMessage(margin + "Stereotype: " + diagramElement.Stereotype, "TRACE");
		logMessage(margin + "Alias: " + diagramElement.Alias, "TRACE");
		logMessage(margin + "Notes: " + diagramElement.Notes, "TRACE");
		logMessage(margin + "ObjectType: " + diagramElement.ObjectType, "TRACE");
		logMessage(margin + "PackageID: " + diagramElement.PackageID, "TRACE");
		logMessage(margin + "ParentID: " + diagramElement.ParentID, "TRACE");
		logMessage(margin + "ClassfierID: " + diagramElement.ClassfierID, "TRACE");
		logMessage(margin + "ClassifierName: " + diagramElement.ClassifierName, "TRACE");
		logMessage(margin + "ClassifierType: " + diagramElement.ClassifierType, "TRACE");
	}

	if (detail && detail >= 2) {
		// Цвета и стили
		logMessage(margin + "BackgroundColor: " + diagramElement.BackgroundColor, "TRACE");
		logMessage(margin + "BorderColor: " + diagramElement.BorderColor, "TRACE");
		logMessage(margin + "FontColor: " + diagramElement.FontColor, "TRACE");

		// Позиция и размеры
		logMessage(margin + "top: " + diagramElement.top, "TRACE");
		logMessage(margin + "bottom: " + diagramElement.bottom, "TRACE");
		logMessage(margin + "left: " + diagramElement.left, "TRACE");
		logMessage(margin + "right: " + diagramElement.right, "TRACE");
		logMessage(margin + "Sequence: " + diagramElement.Sequence, "TRACE");
	}

	if (detail && detail >= 3) {
		// Коллекции
		logMessage(margin + "Attributes.Count: " + (diagramElement.Attributes ? diagramElement.Attributes.Count : 0), "TRACE");
		logMessage(margin + "Connectors.Count: " + (diagramElement.Connectors ? diagramElement.Connectors.Count : 0), "TRACE");
		logMessage(margin + "Constraints.Count: " + (diagramElement.Constraints ? diagramElement.Constraints.Count : 0), "TRACE");
		logMessage(margin + "Methods.Count: " + (diagramElement.Methods ? diagramElement.Methods.Count : 0), "TRACE");
		logMessage(margin + "Operations.Count: " + (diagramElement.Operations ? diagramElement.Operations.Count : 0), "TRACE");
		logMessage(margin + "Ports.Count: " + (diagramElement.Ports ? diagramElement.Ports.Count : 0), "TRACE");
		logMessage(margin + "StateTransitions.Count: " + (diagramElement.StateTransitions ? diagramElement.StateTransitions.Count : 0), "TRACE");
		logMessage(margin + "TaggedValues.Count: " + (diagramElement.TaggedValues ? diagramElement.TaggedValues.Count : 0), "TRACE");
		if (diagramElement.TaggedValues.Count) {
			for (var i=0; i<diagramElement.TaggedValues.Count; i++){
				var tagged = diagramElement.TaggedValues.GetAt(i);
				logMessage(margin + margin + "" + tagged.Name + " " + tagged.Value, "TRACE");
			};
		}
		logMessage(margin + "Properties.Count: " + (diagramElement.Properties ? diagramElement.Properties.Count : 0), "TRACE");
		if (diagramElement.Properties.Count) {
			for (var i=0; i<diagramElement.Properties.Count; i++){
				var property = diagramElement.Properties.Item(i);
				logMessage(margin + margin + "Name= " + property.Name + " Value=" + property.Value, "TRACE");
			};
		}
		logMessage(margin + "CustomProperties.Count: " + (diagramElement.CustomProperties ? diagramElement.CustomProperties.Count : 0), "TRACE");
		if (diagramElement.CustomProperties.Count) {
			for (var i=0; i<diagramElement.CustomProperties.Count; i++){
				var property = diagramElement.CustomProperties.GetAt(i);
				logMessage(margin + margin + "Name= " + property.Name + " Value=" + property.Value, "TRACE");
			};
		}

	}

	logMessage(margin + " ", "TRACE");
}


/**
 * Получает все связи между элементами
 */
function getAllRelationships(elements, currentDiagram) {
    var relationships = new Array();
    var processedRelationships = new Array();
	var diagram as EA.Diagram;
	diagram = currentDiagram;

	for (var z = 0; z < diagram.DiagramLinks.Count; z++) {
		var connector as EA.Connector;
		var diagramLink as EA.DiagramLink;
		diagramLink = diagram.DiagramLinks.GetAt(z);
		if (diagramLink.IsHidden) continue;

		connector = Repository.GetConnectorByID(diagramLink.ConnectorID);

        if (processedRelationships.indexOf(connector.ConnectorID) !== -1) continue;

		var clientElement = elements.find(el => el.ElementID == connector.ClientID); // Repository.GetElementByID(connector.ClientID);
		var supplierElement = elements.find(el => el.ElementID == connector.SupplierID); // Repository.GetElementByID(connector.SupplierID)
        if (clientElement && supplierElement) {
            relationships.push({
                connector: connector,
                client: clientElement,
                supplier: supplierElement,
				diagramLink: diagramLink
            });
            processedRelationships.push(connector.ConnectorID);
			logMessage( "Найдена связь " + connector.Name + " <" + connector.Type + ">  id=" + connector.ConnectorID, "TRACE");
        }
	}

    return relationships;
}


/**
 * Форматирует текст для PlantUML
 */
function formatTextForPlantUML(text) {
    if (!text) return "";

    return text
        .replace(/"/g, '\\"')
        .replace(/\n/g, "\\n")
        .replace(/\r/g, "")
        .trim();
}

function formatNoteForPlantUML(text) {
    if (!text) return "";

    return text
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
        .replace(/{/g, "=")
		.replace(/}/g, "=")
        .trim();
}

function formatNameForPlantUML(text) {
    if (!text) return "";

    return text
        .replace(/"/g, '\\"')
        .replace(/\n/g, "\\n")
        .replace(/\r/g, "")
        .replace(/ /g, '_')
        .replace(/\./g, '-')
        .trim();
//        .replace(/\*/g, '')
}

/**
 * Получает полное имя элемента с пакетами
 */
function getElementFullName(element) {
    var fullName = element.Name;
    var parent = element.Parent;

    while (parent && parent.Type === "Package") {
        fullName = parent.Name + "::" + fullName;
        parent = parent.Parent;
    }

    return fullName;
}

/**
 * Проверяет, является ли элемент видимым на диаграмме
 */
function isElementVisibleOnDiagram(element, diagram) {
    var diagramObjects = diagram.DiagramObjects;

    for (var i = 0; i < diagramObjects.Count; i++) {
        var diagramObject = diagramObjects.GetAt(i);
        if (diagramObject.ElementID === element.ElementID) {
            return true;
        }
    }

    return false;
}

/**
 * Получает теги элемента
 */
function getElementTags(element) {
    var tags = new Array();
    var taggedValues = element.TaggedValues;

    for (var i = 0; i < taggedValues.Count; i++) {
        var taggedValue = taggedValues.GetAt(i);
        tags.push({
            name: taggedValue.Name,
            value: taggedValue.Value,
            notes: taggedValue.Notes
        });
    }

    return tags;
}

/**
 * Получает ограничения элемента
 */
function getElementConstraints(element) {
    var constraints = new Array();
    var elementConstraints = element.Constraints;

    for (var i = 0; i < elementConstraints.Count; i++) {
        var constraint = elementConstraints.GetAt(i);
        constraints.push({
            name: constraint.Name,
            type: constraint.Type,
            notes: constraint.Notes
        });
    }

    return constraints;
}

/**
 * Создает уникальное имя для элемента
 */
function createUniqueElementName(element, elements) {
    var baseName = element.Name;
    var counter = 1;
    var uniqueName = baseName;

    while (elementNameExists(uniqueName, elements)) {
        uniqueName = baseName + "_" + counter;
        counter++;
    }

    return uniqueName;
}

/**
 * Проверяет, существует ли имя элемента
 */
function elementNameExists(name, elements) {
    for (var i = 0; i < elements.length; i++) {
        if (elements[i].Name === name) {
            return true;
        }
    }
    return false;
}

/**
 * Получает информацию о пакете элемента
 */
function getElementPackageInfo(element) {
    var packageInfo = {
        name: "",
        path: new Array(),
        fullPath: ""
    };

    var currentElement = element;

    while (currentElement && currentElement.Type === "Package") {
        packageInfo.path.unshift(currentElement.Name);
        currentElement = currentElement.Parent;
    }

    if (packageInfo.path.length > 0) {
        packageInfo.name = packageInfo.path[packageInfo.path.length - 1];
        packageInfo.fullPath = packageInfo.path.join("::");
    }

    return packageInfo;
}

/**
 * Валидирует диаграмму для экспорта
 */
function validateDiagramForExport(pDiagram) {
	var diagram as EA.Diagram;
	diagram = pDiagram;
    var errors = new Array();
    var warnings = new Array();

    if (!diagram) {
        errors.push("Диаграмма не найдена");
        return { errors: errors, warnings: warnings };
    }

    if (diagram.Type !== "Class" && diagram.Type !== "Component") {
        warnings.push("Диаграмма типа '" + diagram.Type + "' может не поддерживаться полностью");
    }

    var diagramObjects = diagram.DiagramObjects;
    if (diagramObjects.Count === 0) {
        warnings.push("Диаграмма не содержит элементов");
    }

    return { errors: errors, warnings: warnings };
}

/**
 * Логирует сообщения
 */
function logMessage(message, type) {
    var timestamp = new Date().toLocaleTimeString();
    var prefix = "[" + timestamp + "] ";

    switch (type) {
        case "ERROR":
            Session.Output("ОШИБКА: " + prefix + message);
            break;
        case "WARNING":
            Session.Output("ПРЕДУПРЕЖДЕНИЕ: " + prefix + message);
            break;
        case "INFO":
            Session.Output("ИНФО: " + prefix + message);
            break;
        default:
            Session.Output(prefix + message);
    }
}

// Получение ближайшего элемента на диаграмме
function findNearestElement( sourceElement, diagram ){
	// Находим объект на диаграмме
	var sourceDiagramObject = null;
	for (var k = 0; k < diagram.DiagramObjects.Count; k++) {
		if (sourceElement.ElementID == diagram.DiagramObjects.GetAt(k).ElementID) {
			sourceDiagramObject = diagram.DiagramObjects.GetAt(k);
			break;
		}
	}
	var nearestDiagramElement As EA.Element;
	nearestDiagramElement = null;
	var nearestDiagramObject As EA.DiagramObject;
	nearestDiagramObject = null;
	var minDistance = 999999999;
	// Находим ближайший объект на диаграмме
	for (var k = 0; k < diagram.DiagramObjects.Count; k++) {
		var diagramObject as EA.DiagramObject;
		diagramObject = diagram.DiagramObjects.GetAt(k);
		if (diagramObject.ElementID == sourceDiagramObject.ElementID) {
			continue;
		}
		var distance = (sourceDiagramObject.top - diagramObject.top)**2 + (sourceDiagramObject.bottom - diagramObject.bottom)**2 + (sourceDiagramObject.left - diagramObject.left)**2 + (sourceDiagramObject.right - diagramObject.right)**2;
		if (distance < minDistance) {
			minDistance = distance;
			nearestDiagramObject = diagramObject;
		}
	}
	if (nearestDiagramObject) {
		nearestDiagramElement = Repository.GetElementByID( nearestDiagramObject.ElementID );
	}
	return nearestDiagramElement;
}

function getHierarchicalElementName( pElement ){
	var element as EA.Element;
	element = pElement;
	if (element.ParentID) {
		var parentElement As EA.Element;
		parentElement = Repository.GetElementByID(element.ParentID);
		if (parentElement) {
			return getHierarchicalElementName(parentElement) + "." + formatNameForPlantUML(element.Name);
		}
	}
	return formatNameForPlantUML(element.Name);
}

function GetElementColor(elementType, BackgroundColor, defaultColor = null) {
	// receives decimal version of rbg
	// resolve default value if value passed is -1
	// resolve ColorNameByHex
	// LOGTrace("GetColor(" + elementType + " : " + BackgroundColor + ")")
	if (BackgroundColor == -1) {
		if (defaultColor) {
			return defaultColor;
		}
		switch (elementType) {
			case "Sequence": 			return "#lightblue";
			case "Component": 			return "#lightpink";
			case "Class": 				return "#lightpink";
			case "ProvidedInterface": 	return "#lightpink";
			case "Boundary": 			return "#lightgrey";
			case "Note":				return "#lightyellow";
			default:					return "";
		}
	} 
	var hexvalue = BackgroundColor.toString(16);
	hexvalue = ("000000" + hexvalue).slice( -6 );
	var hexRGB = "#" + hexvalue.slice(4) + hexvalue.slice(2, 4) + hexvalue.slice(0, 2);
	var color = ""; // нужно добавить преобразование ColorNameByHex (hexRGB)
	if (color == "") {
		color = hexRGB;
	}
	return color;
}

// Получение имени файла для диаграммы
function getFileNameForDiagram(diagram) {
	var diagramName = diagram.Name;
    var fileName = diagramName.replace(/[^a-zA-Z0-9а-яА-Я]/g, "_") + ".puml";
	var filePath = MakeFilePath(".", fileName);
	return filePath;
}

function getElementAlias( element ){
	return "id"+element.ElementID;
}

// Обновление примечания в элементе
// Обновление выполняется через получение отдельного объекта диаграммы, 
// так как по непонятным причинам может ломаться форматирование при обновлении в открытом объекте.
function ReplaceTextInDiagramNotes( diagramId, newText, textToken ){
	var updatableDiagram as EA.Diagram;
	updatableDiagram = Repository.GetDiagramByID(diagramId);
	var notes = updatableDiagram.Notes;
    const startIndex = notes.indexOf(textToken);
    const endIndex = notes.indexOf(textToken, startIndex + textToken.length);

	var newNotes = notes + "\r\n" + textToken + "\r\n" + newText + "\r\n" + textToken;
    if (startIndex !== -1 && endIndex !== -1) {
		newNotes = notes.slice(0, startIndex + textToken.length) + "\r\n" + newText + "\r\n" + notes.slice(endIndex);
	}

	updatableDiagram.Notes = newNotes;
	return updatableDiagram.Update();
}

function IsDeletedDiagram( aDiagram ) {
	var theDiagram as EA.Diagram;
	theDiagram = aDiagram;
	return theDiagram.Name.slice(0,1) == "-";
}

function IsDeletedPackage( aPackage ) {
	var thePackage as EA.Package;
	thePackage = aPackage;
	return thePackage.Name.slice(0,1) == "-";
}

function IsDeletedElement( anElement ) {
	var theElement as EA.Element;
	theElement = anElement;
	if (!theElement.Name) {
		LOGTrace("IsDeletedElement !theElement.Name = "+theElement.Type);
		return false;
	}
	return theElement.Name.slice(0,1) == "-";
}

