// Get property type value from global project options
function GetPropertyTypeValue( name ) {
	Repository.PropertyTypes.Refresh();
	for (var i=0; i < Repository.PropertyTypes.Count; i++){
		var propertyType as EA.PropertyType;
		propertyType = Repository.PropertyTypes.GetAt(i);
		if (propertyType.Tag == name) {
			return propertyType.Detail;
		}
	}
	return "";
}

// Set property type value to global project options
function SetPropertyTypeValue( name, value, description ) {
	var foundPropertyType as EA.PropertyType;
	foundPropertyType = null;
	for (var i=0; i < Repository.PropertyTypes.Count; i++){
		var propertyType as EA.PropertyType;
		propertyType = Repository.PropertyTypes.GetAt(i);
		if (propertyType.Tag == name) {
			foundPropertyType = propertyType;
		}
	}
	if (!foundPropertyType) {
		var newPropertyType as EA.PropertyType;
		newPropertyType = Repository.PropertyTypes.AddNew(name, description);
		newPropertyType.Description = description;
		newPropertyType.Detail = value;
		newPropertyType.Update();
	} else {
		foundPropertyType.Detail = value;
		foundPropertyType.Update();
	}
	Repository.PropertyTypes.Refresh();
}

