/**
 * Проверяет, поддерживается ли тип элемента в данном типе диаграммы
 */
function isElementTypeSupported(elementType, diagramConfig) {
    return diagramConfig.supportedElements.indexOf(elementType) !== -1;
}


/**
 * Проверяет, поддерживается ли тип связи в данном типе диаграммы
 */
function isRelationshipTypeSupported(relationshipType, diagramConfig) {
    return diagramConfig.supportedRelationships.indexOf(relationshipType) !== -1;
}


function getConnectorType(connector){
	const AGGREGATION_SHARED = 1;
	var theConnector as EA.Connector;
	theConnector = connector;
	var connectorType = theConnector.Type;
	if ((connectorType == "Aggregation") && (theConnector.SupplierEnd.Aggregation != AGGREGATION_SHARED)) {
		connectorType = "Composition";
	}
    return RelationshipTypeMapping[connectorType];
}

/**
 * Получает конфигурацию для типа диаграммы
 */
function getDiagramTypeConfig(diagramType) {
    return DiagramTypeConfig[diagramType] || DiagramTypeConfig["Class"];
}

/**
 * Применяет настройки экспорта
 */
function applyExportConfig(config) {
    for (var key in config) {
        if (ExportConfig.hasOwnProperty(key)) {
            if (typeof config[key] === "object" && !Array.isArray(config[key])) {
                for (var subKey in config[key]) {
                    if (ExportConfig[key].hasOwnProperty(subKey)) {
                        ExportConfig[key][subKey] = config[key][subKey];
                    }
                }
            } else {
                ExportConfig[key] = config[key];
            }
        }
    }
}

/**
 * Сбрасывает настройки к значениям по умолчанию
 */
function resetExportConfig() {
    ExportConfig = {
        options: {
            includeNotes: false,
