}

/**
 * Экспортирует конфигурацию в JSON
 */
function exportConfigToJSON() {
    return JSON.stringify(ExportConfig, null, 2);
}

/**
 * Импортирует конфигурацию из JSON
 */
function importConfigFromJSON(jsonString) {
    try {
        var config = JSON.parse(jsonString);
        applyExportConfig(config);
        return true;
    } catch (error) {
        Session.Output("ОШИБКА при импорте конфигурации: " + error.message);
        return false;
    }
}

!INC Local Scripts.EAConstants-JavaScript
!INC Utils.Diagram-Utils
!INC Utils.File-Utils
!INC PlantUML.PlantUMLConfig

/**
 * Sparx Enterprise Architect to PlantUML Converter (Enhanced Version)
 * Версия: 1.1.0
 * Совместимость: EA 16+
 * 
 * Этот скрипт экспортирует открытую диаграмму классов или компонентов
 * из Sparx Enterprise Architect в формат PlantUML с расширенными возможностями
 * 
 * Промпт:
 * Создай JavaScript код для автоматизации Sparx Enterpirse Architect версии 16 и выше, который для открытой Диаграммы Классов или Диаграммы Компонентов делает выгрузку в виде PlantUML файла. Добавь в скрипт опции для настройки полноты выгрузки (заметки, стереотипы и т.д.). Используй разные цвета для PlantUML элементов.
 * 
 */

/**
 * Основная функция экспорта с расширенными возможностями
 */
function exportStructuralDiagramToPlantUML( diagram, fileName, backupExtention ) {
	if (!existsDirectory(fileName)){
        logMessage("Каталог для файла <"+fileName+"> не существует.", "ERROR");
		return 0;
	};
    var startTime = new Date();
    try {
        logMessage("Начинаем экспорт диаграммы в PlantUML (Enhanced Version)", "INFO");

        // Валидируем диаграмму
        var validation = validateDiagramForExport(diagram);
        if (validation.errors.length > 0) {
            for (var i = 0; i < validation.errors.length; i++) {
                logMessage(validation.errors[i], "ERROR");
            }
            return 0;
        }

        for (var i = 0; i < validation.warnings.length; i++) {
            logMessage(validation.warnings[i], "WARNING");
        }

        logMessage("Диаграмма: " + diagram.Name + " (тип: " + diagram.Type + ")", "INFO");

        // Получаем конфигурацию для типа диаграммы
        var diagramConfig = getDiagramTypeConfig(diagram.Type);

        // Получаем все элементы диаграммы
		var diagramElements = getAllDiagramElementsAndObjects(diagram, ExportConfig.options.maxDepth);

        logMessage("Найдено элементов: " + diagramElements.length, "INFO");

        // Генерируем PlantUML код
        var plantUMLCode = generateEnhancedPlantUMLCode(diagram, diagramElements, diagramConfig);

        // Сохраняем в файл
        saveToFile(plantUMLCode, fileName, backupExtention, "Plantuml (*.puml)|*.puml|All Files (*.*)|*.*||");
//        saveToFile(plantUMLCode, fileName, ExportConfig.file.backupExtension, "Plantuml (*.puml)|*.puml|All Files (*.*)|*.*||");

        var endTime = new Date();
        var processingTime = (endTime - startTime) / 1000;

        logMessage("Экспорт завершен успешно за " + processingTime + " секунд", "INFO");
        logMessage("Файл сохранен: " + fileName, "INFO");
    } catch (error) {
        logMessage("Ошибка при экспорте: " + error.message, "ERROR");
        logMessage("Стек вызовов: " + error.stack, "ERROR");
		throw error;
    }
	return 1;
}


/**
 * Генерирует расширенный PlantUML код для диаграммы
 */
function generateEnhancedPlantUMLCode(diagram, diagramElements, diagramConfig) {
	var diagramName = formatTextForPlantUML(diagram.Name);
    var plantUML = "@startuml " + diagramName + "\n";

    // Добавляем настройки PlantUML
	if (ExportConfig.plantUML.theme) {
		plantUML += "!theme " + ExportConfig.plantUML.theme + "\n";
	}
    plantUML += "skinparam classAttributeIconSize 0\n";
    plantUML += "skinparam backgroundColor " + ExportConfig.plantUML.backgroundColor + "\n";
    plantUML += "skinparam defaultFontName " + ExportConfig.plantUML.defaultFontName + "\n";
    plantUML += "skinparam defaultFontSize " + ExportConfig.plantUML.defaultFontSize + "\n";
    plantUML += "skinparam roundCorner " + ExportConfig.plantUML.roundCorner + "\n";
    plantUML += "skinparam shadowing " + (ExportConfig.plantUML.shadowing ? "true" : "false") + "\n";
    plantUML += "skinparam maxMessageSize " + ExportConfig.plantUML.maxMessageSize + "\n";
    plantUML += "skinparam wrapWidth " + ExportConfig.plantUML.wrapWidth + "\n";
    plantUML += "skinparam linetype ortho\n";
    plantUML += diagramConfig.params.join("\n");
	plantUML += "\n\n";

    // Добавляем заголовок
    plantUML += "title " + diagramName + "\n\n";

	diagramElements.filter(e => !isElementTypeSupported(e.Type, diagramConfig)).forEach(function(element){
		logMessage("Элемент <"+element.Name+"> с типом <"+element.Type+"> не поддерживается для диаграммы данного типа <"+diagram.Type+">.","WARNING");
	});

	var supportedElements = diagramElements.filter(e => isElementTypeSupported(e.Type, diagramConfig));
	plantUML += generateEnhancedAllElementCode(supportedElements, diagram, diagramConfig);

    // Генерируем связи между элементами
    if (ExportConfig.options.includeRelationships) {
        var relationships = getAllRelationships(diagramElements, diagram);
        plantUML += generateEnhancedRelationshipsCode(relationships, diagramConfig);
    }

    plantUML += "@enduml\n";
    return plantUML;
}

/**
 * Формирование кода для всех элементов
 */
function generateEnhancedAllElementCode(diagramElements, diagram, diagramConfig){
	// Подготовка PlantUML структуры
	var plantUMLStructureList = [];
	diagramElements.forEach(function(diagramElement){
		// Может возвращаться список структур на один элемент
        plantUMLStructureForElement = generateEnhancedElementCode(diagramElement, diagram, diagramConfig, diagramElements);
		if (plantUMLStructureForElement){
			plantUMLStructureList = plantUMLStructureList.concat(plantUMLStructureForElement);
		}
	});
	logMessage("Подготовлено "+plantUMLStructureList.length+" элементов PlantUML из "+diagramElements.length+" элементов EA", "INFO");
	// Сортируем элементы
	plantUMLStructureList = plantUMLStructureList.sort((a, b) => (a.left - b.left)*100000 + (b.top - a.top));

	// Тестовый вывод информации
	plantUMLStructureList.forEach(function(e){
		// logMessage("*** "+e.elementName+" <"+e.elementType+"> <<"+e.elementStereotype+">> ElementID="+e.elementId+"  ParentID="+e.parentId+" left="+e.left+"  top="+e.top+"  Subtype="+e.elementSubtype, "INFO");
	});


	// Построение иерархии элементов для Boundary
	plantUMLStructureList.filter(e => e.elementType == "Boundary").sort((a,b) => a.sequence - b.sequence).forEach(function(boundaryStructure){
		// Получение элементов, без родителя и которые вложены в Boundary
		plantUMLStructureList.filter(e => 
			!e.parentId && 
			e.elementId != boundaryStructure.elementId &&
			e.left >= boundaryStructure.left &&
			e.right <= boundaryStructure.right &&
			e.top <= boundaryStructure.top &&
			e.bottom >= boundaryStructure.bottom 
		).forEach(function(includedStructure){
			// logMessage("*** Элемент <"+ includedStructure.elementName + "> "+includedStructure.elementType+" привязан к Boundary.", "INFO");
			includedStructure.parentId = boundaryStructure.elementId;
		});
	});

	// Формирование кода элементов
	var code = "";
	plantUMLStructureList.filter(e => !plantUMLStructureList.some(p => p.elementId == e.parentId)).forEach(function(structure){
		code += UpdatePlantUMLStructureContent( structure, plantUMLStructureList, 0 ) + "\n";
	});
	plantUMLStructureList.filter(e => !e.processeed).forEach(function(structure){
		logMessage("Элемент <"+structure.elementName+"> не обработан для добавления на PlantUML диаграмму.","ERROR");
	});

	return code;
}

function UpdatePlantUMLStructureContent( structure, structureList, level ){
	const indentSpaces = level ? " ".repeat(level*3) : "";
	structureList.filter(s => s.parentId && structure.elementId && s.parentId == structure.elementId).forEach(function(childStructure){
		if (!structure.content.length){
			structure.header += " {";
			structure.footer += "}";
		}
		structure.content += UpdatePlantUMLStructureContent( childStructure, structureList, level + 1 );
	});
	structure.processeed = true;
	structure.code = indentSpaces + structure.header + "\n";
	if (structure.content.length) {
		structure.code += indentSpaces + structure.content.replace("\n", "\n"+indentSpaces) ;
	}
	if (structure.footer.length) {
		structure.code += structure.footer.replace("\n", "\n"+indentSpaces) + "\n";
	}
	return structure.code;
}

function GetPlantUMLStructure(diagramElement){
	var result = {
		header: "",
		footer: "",
		content: "",
		code: "",
		elementName: diagramElement.Name,
		elementType: diagramElement.Type,
		elementId: diagramElement.ElementID,
		elementStereotype: diagramElement.Stereotype,
		elementSubtype: diagramElement.Subtype,
		parentId: diagramElement.ParentID,
		left: (diagramElement.left ? diagramElement.left : 999999),
		right: (diagramElement.right ? diagramElement.right : 999999),
		top: (diagramElement.top ? diagramElement.top : 999999),
		bottom: (diagramElement.bottom ? diagramElement.bottom : 999999),
		sequence: (diagramElement.Sequence ? diagramElement.Sequence: 0),
		processeed: false
	};
	return result;
}

/**
 * Генерирует расширенный PlantUML код для элемента
 */
function generateEnhancedElementCode(diagramElement, pDiagram, diagramConfig, diagramElements) {
	var diagram as EA.Diagram;
	diagram = pDiagram;

    var code = GetPlantUMLStructure(diagramElement);
	var elementCodeList = [code];

    var elementType = diagramElement.Type;
    var elementName = diagramElement.Name; // getHierarchicalElementName(element);
	var elementAlias = getElementAlias(diagramElement);
    var elementStereotype = diagramElement.Stereotype;
    var elementNotes = (diagramElement.Notes ? diagramElement.Notes.trim() : null);

    // Получаем уникальное имя элемента
    var uniqueName = createUniqueElementName(diagramElement, diagramElements);

    // Определяем цвет элемента
    var elementColor = getElementColor(elementType);
	elementColor = GetElementColor(elementType, diagramElement.BackgroundColor, elementColor);

    // Начинаем определение элемента
    var plantUMLType = ElementTypeMapping[elementType] || "class";
	if (plantUMLType == "unused"){
		logMessage("Элемент "+elementName+" <"+elementType+"> не нужен на диаграмме","TRACE");
		return null;
	}
	var plantUMLConfig = PlantUMLTypeConfig[plantUMLType];
	if (!plantUMLConfig){
		logMessage("Не найдена конфигурация для plantUMLType = "+plantUMLType+"", "ERROR");
		return;
	}
	const elementIsNote = (plantUMLType.toLowerCase() == "note");

	if (!elementIsNote) {
		code.header += plantUMLType + " \"" + elementName + "\" as " + elementAlias;

		// Добавляем стереотип
		if (ExportConfig.options.includeStereotypes && elementStereotype && plantUMLConfig.includeStereotypes) {
			code.header += " <<" + formatTextForPlantUML(elementStereotype) + ">>";
		}

		// Добавляем модификаторы
		if (element.Abstract === "1"  && plantUMLConfig.includeStereotypes) {
			code.header += " <<abstract>>";
		}

		// Добавляем цвет
		if (ExportConfig.options.includeColors && elementColor) {
			code.header += " #" + elementColor.replace("#", "");
		}

		// Добавляем атрибуты
		if (ExportConfig.options.includeAttributes && diagramConfig.includeAttributes && plantUMLConfig.includeAttributes) {
			code.content += generateEnhancedAttributesCode(diagramElement);
		}

		// Добавляем методы
		if (ExportConfig.options.includeMethods && diagramConfig.includeMethods && plantUMLConfig.includeMethods) {
			code.content += generateEnhancedMethodsCode(diagramElement);
		}

		// Добавляем операции (для компонентов)
		if (ExportConfig.options.includeOperations && plantUMLConfig.includeOperations) {
			code.content += generateOperationsCode(diagramElement);
		}

		// Добавляем свойства
		if (ExportConfig.options.includeProperties && plantUMLConfig.includeProperties) {
			code.content += generatePropertiesCode(diagramElement);
		}

		// Добавляем порты (для компонентов)
		if (ExportConfig.options.includePorts && plantUMLConfig.includePorts) {
			code.content += generatePortsCode(diagramElement);
		}

		if (code.content.length) {
			code.header += " {";
			code.footer += "}";
		}
	}

	// Обрабатываем заметки отдельно
	if (elementIsNote && elementNotes) {
		var nearestDiagramElement As EA.Element;
		nearestDiagramElement = findNearestElement(diagramElement, diagram);
		if (nearestDiagramElement) {
			// code.header += "note right of " + getHierarchicalElementName(nearestDiagramElement);
			code.header += "note as " + elementAlias;
			code.content += "  " + formatTextForPlantUML(elementNotes).replace(/\\n/g, "\n  ") + "\n";
			code.footer += "end note";
		}
	}

    // Добавляем заметки к элементу
    if (plantUMLConfig.includeNotes && elementNotes && !elementIsNote) {
		var noteCode = GetPlantUMLStructure(UnionDiagramObjectAndElement(diagramElement, {Type: "Note", Name: "Note_for_"+elementName, ElementID: 1000000 + element.ElementID}));
        noteCode.header += "note right of " + elementAlias;
        noteCode.content += "  " + formatTextForPlantUML(elementNotes).replace(/\\n/g, "\n  ") + "\n";
        noteCode.footer += "end note";
		elementCodeList.push(noteCode);
    }

    // Добавляем теги
    if (ExportConfig.options.includeTags) {
        var tags = getElementTags(element);
        if (tags.length > 0) {
			var noteCode = GetPlantUMLStructure(UnionDiagramObjectAndElement(diagramElement, {Type: "Note", Name: "Tags_for_"+elementName, ElementID: 2000000 + element.ElementID}));
            noteCode.header += "note bottom of " + elementAlias;
            noteCode.content += "  **Теги:**\n";
            for (var i = 0; i < tags.length; i++) {
                noteCode.content += "  - " + formatTextForPlantUML(tags[i].name) + ": " + formatTextForPlantUML(tags[i].value) + "\n";
            }
            noteCode.footer += "end note";
			elementCodeList.push(noteCode);
        }
    }

    // Добавляем ограничения
    if (ExportConfig.options.includeConstraints) {
        var constraints = getElementConstraints(element);
        if (constraints.length > 0) {
			var noteCode = GetPlantUMLStructure(UnionDiagramObjectAndElement(diagramElement, {Type: "Note", Name: "Constraints_for_"+elementName, ElementID: 2000000 + element.ElementID}));
            noteCode.header += "note left of " + elementAlias;
            noteCode.content += "  **Ограничения:**\n";
            for (var i = 0; i < constraints.length; i++) {
                noteCode.content += "  - " + formatTextForPlantUML(constraints[i].name) + " (" + constraints[i].type + ")\n";
            }
            noteCode.footer += "end note";
			elementCodeList.push(noteCode);
        }
    }

    return elementCodeList;
}

/**
 * Генерирует расширенный код атрибутов
 */
function generateEnhancedAttributesCode(diagramElement) {
    var code = "";
    var attributes = diagramElement.Attributes;

    for (var i = 0; i < attributes.Count; i++) {
		var attribute as EA.Attribute;
        attribute = attributes.GetAt(i);
		var isCollection = attribute.IsCollection || attribute.LowerBound !== "1" || attribute.UpperBound !== "1";
        var visibility = VisibilityMapping[attribute.Visibility] || "+";
        var name = attribute.Name;
        var type = attribute.Type;
        var stereotype = attribute.Stereotype;
        var notes = attribute.Notes;
        var defaultValue = attribute.Default;
        var isStatic = attribute.IsStatic === "1";
        var isConst = attribute.IsConst === "1";

        code += "  " + visibility + " ";

        if (isStatic) code += "{static} ";
        if (isConst) code += "{readonly} ";

        code += formatTextForPlantUML(name);

        if (type) {
            code += " : " + formatTextForPlantUML(type);
        }

		if (isCollection) {
            code += " [" + attribute.LowerBound + ".." + attribute.UpperBound + "]";
		}

        if (defaultValue) {
            code += " = " + formatTextForPlantUML(defaultValue);
        }

        if (ExportConfig.options.includeStereotypes && stereotype) {
            code += " <<" + formatTextForPlantUML(stereotype) + ">>";
        }

        if (ExportConfig.options.includeNotes && notes) {
            code += " // " + formatTextForPlantUML(notes);
        }

        code += "\n";
    }

    return code;
}

/**
 * Генерирует расширенный код методов
 */
function generateEnhancedMethodsCode(diagramElement) {
    var code = "";
    var methods = diagramElement.Methods;

    for (var i = 0; i < methods.Count; i++) {
        var method = methods.GetAt(i);
        var visibility = VisibilityMapping[method.Visibility] || "+";
        var name = method.Name;
        var returnType = method.ReturnType;
        var parameters = method.Parameters;
        var stereotype = method.Stereotype;
        var notes = method.Notes;
        var isStatic = method.IsStatic === "1";
        var isAbstract = method.IsAbstract === "1";

        code += "  " + visibility + " ";

        if (isStatic) code += "{static} ";
        if (isAbstract) code += "{abstract} ";

        code += formatTextForPlantUML(name) + "(";

        // Добавляем параметры
        for (var j = 0; j < parameters.Count; j++) {
			var param as EA.Parameter;
            param = parameters.GetAt(j);
            if (j > 0) code += ", ";
            code += formatTextForPlantUML(param.Name) + " : " + formatTextForPlantUML(param.Type);
        }

        code += ")";

        if (returnType) {
            code += " : " + formatTextForPlantUML(returnType);
        }

        if (ExportConfig.options.includeStereotypes && stereotype) {
            code += " <<" + formatTextForPlantUML(stereotype) + ">>";
        }

        if (ExportConfig.options.includeNotes && notes) {
            code += " // " + formatTextForPlantUML(notes);
        }

        code += "\n";
    }

    return code;
}

/**
 * Генерирует код операций (для компонентов)
 */
function generateOperationsCode(diagramElement) {
    var code = "";
    var operations = diagramElement.Operations;
	if (!operations){
		return code;
	}

    for (var i = 0; i < operations.Count; i++) {
        var operation = operations.GetAt(i);
        var name = operation.Name;
        var stereotype = operation.Stereotype;
        var notes = operation.Notes;

        code += "  + " + formatTextForPlantUML(name) + "()";

        if (ExportConfig.options.includeStereotypes && stereotype) {
            code += " <<" + formatTextForPlantUML(stereotype) + ">>";
        }

        if (ExportConfig.options.includeNotes && notes) {
            code += " // " + formatTextForPlantUML(notes);
        }

        code += "\n";
    }

    return code;
}

/**
 * Генерирует код свойств
 */
function generatePropertiesCode( diagramElement) {
    var code = "";
    var properties = diagramElement.Properties;
	if (!properties){
		return code;
	}

    for (var i = 0; i < properties.Count; i++) {
        var property = properties.Item(i);
        var name = property.Name;
        var value = property.Value;
        var notes = property.Notes;

        if (value || notes) {
            code += "   " + formatNameForPlantUML(name);

            if (value) {
                code += " = " + formatNameForPlantUML(value);
            }

            if (ExportConfig.options.includeNotes && notes) {
                code += " // " + formatTextForPlantUML(notes);
            }

            code += "\n";
        }
    }

    return code;
}

/**
 * Генерирует код портов (для компонентов)
 */
function generatePortsCode(diagramElement) {
    var code = "";
    var ports = diagramElement.Ports;
	if (!ports){
		return code;
	}

    for (var i = 0; i < ports.Count; i++) {
        var port = ports.GetAt(i);
        var name = port.Name;
        var stereotype = port.Stereotype;
        var notes = port.Notes;

        code += "  + [port] " + formatTextForPlantUML(name);

        if (ExportConfig.options.includeStereotypes && stereotype) {
            code += " <<" + formatTextForPlantUML(stereotype) + ">>";
        }

        if (ExportConfig.options.includeNotes && notes) {
            code += " // " + formatTextForPlantUML(notes);
        }

        code += "\n";
    }

    return code;
}

/**
 * Генерирует расширенный код связей
 */
function generateEnhancedRelationshipsCode(relationships, diagramConfig) {
    var code = "";
    var processedRelationships = new Array();

    for (var i = 0; i < relationships.length; i++) {
        var relationship = relationships[i];
        var connector = relationship.connector;

        var connectorID = connector.ConnectorID;
        if (processedRelationships.indexOf(connectorID) !== -1) continue;

        // Проверяем, поддерживается ли тип связи
        if (diagramConfig.supportedRelationships.indexOf(connector.Type) === -1) {
			logMessage("Тип связи " + connector.Type + " между элементами <"+relationship.client.Name+"> и <"+relationship.supplier.Name+"> не поддерживается.","WARNING");
			continue;
		}

        code += generateEnhancedRelationshipCode(connector, relationship.client, relationship.supplier);
        processedRelationships.push(connectorID);
    }

    return code;
}

/**
 * Генерирует расширенный код для одной связи
 */
function generateEnhancedRelationshipCode(pConnector, clientElement, supplierElement) {
	var connector as EA.Connector;
	connector = pConnector;

    var code = "";
    var clientAlias = getElementAlias(clientElement); // getHierarchicalElementName(sourceElement);
    var supplierAlias = getElementAlias(supplierElement); // getHierarchicalElementName(targetElement);
    var connectorType = connector.Type;
    var connectorName = connector.Name;
    var connectorStereotype = connector.Stereotype;
    var connectorNotes = connector.Notes;
    var connectorDirection = connector.Direction;

    // Определяем тип связи в PlantUML
    var relationshipMapping = getConnectorType(connector);

	if (!relationshipMapping) {
		logMessage("Неизвестный тип связи " + connector.Type + " <" + connector.Direction + "> между элементами <"+clientElement.Name+"> и <"+supplierElement.Name+">.","WARNING");
		relationshipMapping = RelationshipTypeMapping[0];
	}
	var plantUMLType = relationshipMapping[connectorDirection];
	if (!plantUMLType){
		logMessage("Неизвестное направление связи " + connector.Type + " <" + connector.Direction + "> между элементами <"+clientElement.Name+"> и <"+supplierElement.Name+">.","WARNING");
		plantUMLType = relationshipMapping["Unspecified"];
	}
	// logMessage("*** Связь " + connector.Type + " <" + connector.Direction + "> <<"+connector.Stereotype+">> между элементами client=<"+clientElement.Name+"> и supplier=<"+supplierElement.Name+"> plantUMLType="+plantUMLType,"TRACE");

	//
	// logMessage("*** Переход " + connector.Type + " <" + connector.Direction + "> <<"+connector.Stereotype+">> " + connector.TransitionEvent + " - " + connector.TransitionGuard,"TRACE");
	/*
	if (connector.Constraints.Count) {
		for (var i=0; i < connector.Constraints.Count; i++) {
			var constr as EA.Constraint;
			constr = connector.Constraints.GetAt(i);
			constr.Type
			logMessage("*** Ограничение " + connector.Type + " <" + connector.Direction + "> <<"+connector.Stereotype+">> " + constr.Name + " - " + constr.Notes,"TRACE");
		}
	}
	*/

	var clientCardinality = (connector.ClientEnd.Cardinality ? "\"" + connector.ClientEnd.Cardinality + "\"": "");
	var supplierCardinality = (connector.SupplierEnd.Cardinality ? "\"" + connector.SupplierEnd.Cardinality + "\"" : "");

    code += "" + clientAlias + " " + clientCardinality + " " + plantUMLType + " " + supplierCardinality + " " + supplierAlias + "";

	var codeName = "";
    if (connectorName) {
        codeName += formatTextForPlantUML(connectorName);
    }
    if (ExportConfig.options.includeStereotypes && connectorStereotype) {
        codeName += " <<" + formatTextForPlantUML(connectorStereotype) + ">>";
    }
	if (connector.TransitionGuard) {
		codeName += " \\n[" + connector.TransitionGuard + "]";
	}
	if (connector.TransitionAction) {
		codeName += " / " + connector.TransitionAction + "]";
	}

	if (codeName) {
		code += " : " + codeName;
	}


    if (ExportConfig.options.includeNotes && connectorNotes) {
        code += " // " + formatTextForPlantUML(connectorNotes);
    }

    code += "\n";
    return code;
}

/**
 * Получает цвет для типа элемента
 */
function getElementColor(elementType) {
    return ExportConfig.colors[elementType.toLowerCase()] || ExportConfig.colors.class;
}

!INC Local Scripts.EAConstants-JavaScript
!INC Utils.Diagram-Utils
!INC Utils.File-Utils
!INC PlantUML.PlantUMLConfig

/**
 * Sparx Enterprise Architect to PlantUML Converter (Enhanced Version)
 * Версия: 1.1.0
 * Совместимость: EA 16+
 * 
 * Этот скрипт экспортирует открытую диаграмму классов или компонентов
 * из Sparx Enterprise Architect в формат PlantUML с расширенными возможностями
 * https://sparxsystems.com/enterprise_architect_user_guide/17.0/add-ins___scripting/reference.html
 * 
 */

/**
 * Основная функция экспорта с расширенными возможностями
 */
function exportActivityDiagramToPlantUML( diagram, fileName, backupExtention ) {
	if (!existsDirectory(fileName)){
        logMessage("Каталог для файла <"+fileName+"> не существует.", "ERROR");
		return 0;
	};
    var startTime = new Date();
    try {
        logMessage("Начинаем экспорт диаграммы Деятельности в PlantUML", "INFO");

        // Валидируем диаграмму
        var validation = validateDiagramForExport(diagram);
        if (validation.errors.length > 0) {
            for (var i = 0; i < validation.errors.length; i++) {
                logMessage(validation.errors[i], "ERROR");
            }
            return 0;
        }

        for (var i = 0; i < validation.warnings.length; i++) {
            logMessage(validation.warnings[i], "WARNING");
        }

        logMessage("Диаграмма: " + diagram.Name + " (тип: " + diagram.Type + ")", "INFO");

        // Получаем конфигурацию для типа диаграммы
        var diagramConfig = getDiagramTypeConfig(diagram.Type);

        // Получаем все элементы диаграммы
		var diagramElements = getAllDiagramElementsAndObjects(diagram, ExportConfig.options.maxDepth);
        var relationships = getAllRelationships(diagramElements, diagram);

        // Генерируем PlantUML код
        var plantUMLCode = generateActivityDiagramPlantUMLCode(diagram, diagramElements, relationships, diagramConfig);

        // Сохраняем в файл
        saveToFile(plantUMLCode, fileName, backupExtention, "Plantuml (*.puml)|*.puml|All Files (*.*)|*.*||");
//        saveToFile(plantUMLCode, fileName, ExportConfig.file.backupExtension, "Plantuml (*.puml)|*.puml|All Files (*.*)|*.*||");

        var endTime = new Date();
        var processingTime = (endTime - startTime) / 1000;

        logMessage("Экспорт завершен успешно за " + processingTime + " секунд", "INFO");
        logMessage("Файл сохранен: " + fileName, "INFO");
    } catch (error) {
        logMessage("Ошибка при экспорте: " + error.message, "ERROR");
        logMessage("Стек вызовов: " + error.stack, "ERROR");
		throw error;
    }
	return 1;
}


/**
 * Генерирует расширенный PlantUML код для диаграммы
 */
function generateActivityDiagramPlantUMLCode(diagram, diagramElements, relationships, diagramConfig) {
	var diagramName = formatTextForPlantUML(diagram.Name);
    var plantUML = "@startuml " + diagramName + "\n";

    // Добавляем настройки PlantUML
	if (ExportConfig.plantUML.theme) {
		plantUML += "!theme " + ExportConfig.plantUML.theme + "\n";
	}
    plantUML += "skinparam classAttributeIconSize 0\n";
    plantUML += "skinparam backgroundColor " + ExportConfig.plantUML.backgroundColor + "\n";
    plantUML += "skinparam defaultFontName " + ExportConfig.plantUML.defaultFontName + "\n";
    plantUML += "skinparam defaultFontSize " + ExportConfig.plantUML.defaultFontSize + "\n";
    plantUML += "skinparam roundCorner " + ExportConfig.plantUML.roundCorner + "\n";
    plantUML += "skinparam shadowing " + (ExportConfig.plantUML.shadowing ? "true" : "false") + "\n";
    plantUML += "skinparam maxMessageSize " + ExportConfig.plantUML.maxMessageSize + "\n";
    plantUML += "skinparam wrapWidth " + ExportConfig.plantUML.wrapWidth + "\n";
    plantUML += "skinparam linetype ortho\n";
    plantUML += diagramConfig.params.join("\n");
	plantUML += "\n\n";

    // Добавляем заголовок
    plantUML += "title " + diagramName + "\n\n";

    logMessage("Найдено элементов: " + diagramElements.length + ", найдено связей: " + relationships.length, "INFO");
	diagramElements.forEach(function(diagramElement){
		logDiagramElement(diagramElement, 0);
	});

	diagramElements.filter(e => !isElementTypeSupported(e.Type, diagramConfig)).forEach(function(element){
		logMessage("Элемент <"+element.Name+"> с типом <"+element.Type+"> не поддерживается для диаграммы данного типа <"+diagram.Type+">.","WARNING");
	});

	var supportedElements = diagramElements.filter(e => isElementTypeSupported(e.Type, diagramConfig));

	// Фильтруем связи
	const SUPPORTED_LINKS = ["ControlFlow", "NoteLink", "Dependency111"];
	var notSupportedLinks = relationships.filter(r => !SUPPORTED_LINKS.includes(r.connector.Type));
	if (notSupportedLinks.length){
		logMessage("Обнаружены не поддерживаемые типы связей: "+notSupportedLinks.map(r => "<"+r.connector.Type+">").join(", "),"WARNING");
	}

	var supportedRelationships = relationships.filter(r => SUPPORTED_LINKS.includes(r.connector.Type));

	var nodes = buildGraph(supportedElements, supportedRelationships);
	plantUML += generateActivityDiagramAllElementCode(nodes, diagram, diagramConfig);

    plantUML += "@enduml\n";
    return plantUML;
}

// Построение графа элементов
function buildGraph(diagramElements, relationships){
	logMessage("Построение графа элементов.", "INFO");
	var nodes = [];
	// Создается графовая структура
	diagramElements.forEach(function(diagramElement){
		var node = createNode(diagramElement);
		if (node) {
			nodes.push( node );
		}
	});
	// Заполнение связей
	const NOTE_LINKS = ["NoteLink"];
	const NOTE_TYPES = ["Note"];
	nodes.filter(node => !NOTE_TYPES.includes(node.diagramElement.Type)).forEach(function(node){
		node.outcomeLinks = relationships.filter(r => r.client.ElementID == node.diagramElement.ElementID && !NOTE_LINKS.includes(r.connector.Type)).
			map(r => createLink(r, nodes.find(e => e.diagramElement.ElementID == r.supplier.ElementID))).
			filter(e => e.node);
		node.incomeLinks = relationships.filter(r => r.supplier.ElementID == node.diagramElement.ElementID && !NOTE_LINKS.includes(r.connector.Type)).
			map(r => createLink(r, nodes.find(e => e.diagramElement.ElementID == r.client.ElementID))).
			filter(e => e.node);
		logMessage("Обработан элемент <" +node.name + "> (" + node.diagramElement.ElementID + ")   outcomeLinks=" + node.outcomeLinks.map(outcome => outcome.node.id).join(",")+ "   incomeLinks="+node.incomeLinks.map(income => income.node.id).join(","), "INFO");
	});
	// Отдельно устанавливаются связи с заметками
	nodes.filter(node => NOTE_TYPES.includes(node.diagramElement.Type)).forEach(function(note){
		// У заметки только входящие связи:
		var rNodes = relationships.filter(r => r.client.ElementID == note.diagramElement.ElementID).
			map(r => createLink(r, nodes.find(e => e.diagramElement.ElementID == r.supplier.ElementID))).
			filter(e => e.node).
			map(e => e.node);
		rNodes = rNodes.concat( relationships.filter(r => r.supplier.ElementID == note.diagramElement.ElementID).
			map(r => createLink(r, nodes.find(e => e.diagramElement.ElementID == r.client.ElementID))).
			filter(e => e.node).
			map(e => e.node) );
		// Добавляем обратные связи:
		rNodes.forEach((node) => {
			if (!node.noteNodes) {
				node.noteNodes = [note];
			} else {
				node.noteNodes.push(note);
			}
		});
		logMessage("Заметка <" +(note.name ? note.name : note.notes.slice(0,20)) +"> (" + note.diagramElement.ElementID + ")   привязана к узлам=[" + rNodes.map(node => "<"+node.name + " (" + node.id + ")>").join(",")+"]", "INFO");
	});

	// Заполнение свойств узлов
	nodes.forEach(function(node){
		node.properties = getNodeProperties(node);
	});
	var exludedNodes = nodes.filter(node => !node.properties);
	if (exludedNodes.length){
		logMessage("Из диаграммы исключены необрабатываемые элементы [" + exludedNodes.map(node => node.name).join(", ") + "]", "INFO");
	}
	nodes = nodes.filter(node => node.properties);

	return indexingGraph(nodes);
}

// Индексация графа от корневых элементов
function indexingGraph(nodes){
	const PARTITION_NODE = "partition";
	// Функция рекурсивного обхода
	function bypassNode(node, index, partitionLevel){
		if (node.isProcessed) {
			return;
		}
		node.isProcessed = true;
		node.index = index;
		node.partitionLevel = partitionLevel - node.incomeLinks.length;
		// logMessage("bypassNode node=<"+node.name+"> income="+node.incomeLinks.length+" outcome="+node.outcomeLinks.length+" level=<"+node.partitionLevel+">","TRACE");
		if (node.outcomeLinks) {
			node.outcomeLinks.forEach(function(link){
				bypassNode(link.node, index+1, node.partitionLevel + node.outcomeLinks.length);
			});
		}
	}
	// Сбрасываем признак обработки
	resetNodeProcessed(nodes);
	// Пока есть не обработанные элементы обрабатываем их
	var beforeLength = 0;
	var afterLength = nodes.filter(n => !n.isProcessed && n.properties && n.properties.type != PARTITION_NODE).length;
	while (afterLength && beforeLength != afterLength ){
		beforeLength = afterLength;
		// Поиск корневого элемента, который не является разделом
		var rootNode = nodes.find(n => !n.isProcessed && !n.incomeLinks.length && n.properties && n.properties.type != PARTITION_NODE);
		if (rootNode) {
			logMessage("Индексируем граф для корневого элемента: <" + rootNode.name + ">", "INFO");
		} else {
			// Если корневой элемент не найден, берем в соответствии с расположением на диаграмме
			logMessage("На диаграмме не найден корневой элемент для необработанных элементов, выбираем первый в соответствии с расположением на диаграмме.", "WARNING");
			rootNode = nodes.filter(n => !n.isProcessed && n.properties && n.properties.type != PARTITION_NODE).sort((a,b) => (a.diagramElement.left - b.diagramElement.left) + (a.diagramElement.top - b.diagramElement.top)*100)[0];
		}
		// Обработка корневого элемента
		rootNode.isRoot = true;
		bypassNode(rootNode, 0, 0);
		afterLength = nodes.filter(n => !n.isProcessed && n.properties && n.properties.type != PARTITION_NODE).length;
	}
	if (afterLength) {
		var notProcessed = nodes.filter(n => !n.isProcessed && n.properties && n.properties.type != PARTITION_NODE);
		logMessage("Не удалось обработать " + afterLength + " элементов делаем их корневыми: [" + notProcessed.map(node => node.name).join(", ") + "]", "ERROR");
		nodes.filter(n => !n.isProcessed && n.properties && n.properties.type != PARTITION_NODE).forEach(function(node){
			node.isRoot = true;
			node.index = 0;
		});
	} else {
		logMessage("Обработка элементов выполнена полностью", "INFO");
	}

	// Обратная сортировка в соответствии с индексом
	var sortedNodes = nodes.sort((a,b) => -((a.index - b.index)*10000 + (a.diagramElement.left - b.diagramElement.left) + (a.diagramElement.top - b.diagramElement.top)));
	// Добавляем разделы (partition)
	var partitions = sortedNodes.filter(n => n.properties && n.properties.type == PARTITION_NODE);
	partitions.forEach(function(partition){
		var isIncluded = false;
		sortedNodes.filter(node => node.isRoot).forEach(function(rootNode){
			logMessage("Анализ региона <"+partition.name+"> для rootNode=<"+rootNode.name+">.","INFO");
			if (includePartition(rootNode, partition, null)) {
				isIncluded = true;
				logMessage("Регион <"+partition.name+"> включен в граф.","INFO");
			} else {
				if (isIncluded) {
					// если уже регион включен, то игнорируем
					return;
				}
				// если не смогли включить в граф, то делаем элемент корневым, чтобы он не потерялся
				partition.isRoot = true;
				partition.index = 0;
				logMessage("Регион <"+partition.name+"> не включен в граф.","WARNING");
			}
		});
	});

	logMessage("На диаграмме найдены корневые элементы: [" + nodes.filter(n => n.isRoot).map(node => "<"+node.name+">").join(", ") +"].", "INFO");
	return sortedNodes;
}

// включение раздела в граф узлов
function includePartition(node, partition, aStartPartitionNode){
	var startPartitionNode = aStartPartitionNode;
	var start = false;
	logMessage("partition=<"+partition.name+">  node=<"+node.name+"> parentId=<"+node.parentId+"> level="+node.partitionLevel+" aStartPartitionNode=<"+(aStartPartitionNode ? aStartPartitionNode.name : "null")+">","TRACE");
	if (
		startPartitionNode && 
		(node.parentId != partition.id || !node.outcomeLinks.length) && 
		startPartitionNode.partitionLevel >= node.partitionLevel
	){
		// нашли конец региона, перед этим узлом нужно завершать регион
		node.endPartitionNode = partition;
		logMessage("Найден конец региона partition=<"+partition.name+">  node=<"+node.name+"> parentId=<"+node.parentId+"> level="+node.partitionLevel+" aStartPartitionNode=<"+(aStartPartitionNode ? aStartPartitionNode.name : "null")+">","TRACE");
		return true;
	}
	if (!startPartitionNode && node.parentId == partition.id && node.incomeLinks.length <= 1){
		// Нашли начало региона, перед этим узлом нужно начинать регион
		start = true;
		startPartitionNode = node;
		node.beginPartitionNode = partition;
		logMessage("Найдено начало региона partition=<"+partition.name+">  node=<"+node.name+"> parentId=<"+node.parentId+"> level="+node.partitionLevel+" aStartPartitionNode=<"+(aStartPartitionNode ? aStartPartitionNode.name : "null")+">","TRACE");
	}
	var result = false;
	node.outcomeLinks.forEach(function(link){
		result = includePartition(link.node, partition, startPartitionNode) || result;
	});
	if (!result && start) {
		// не нашли конец, поэтому сбрасываем
		partition.partitionLevel = 0;
		node.beginPartitionNode = null;
	}
	return result;
}


// Создание структуры узла графа
function createNode(diagramElement) {
	var node = {
		id: diagramElement.ElementID,
		name: getElementName(diagramElement),
		notes: getElementNotes(diagramElement),
		parentId: diagramElement.ParentID,
		properties: null,
		outcomeLinks: [],
		incomeLinks: [],
		noteNodes: [],						// Заметки, относящиеся к данному элементу
		isRoot: false,						// признак, что элемент корневой (может не существовать явно на диаграмме)
		isProcessed: false,					// признак, что элемент обработан
		isDeleted: false,					// признак удаления
		index: 0,							// порядковый номер элемента для обработки
		code: "",							// PlantUML код
		partitionLevel: 0,					// Уровень распараллеливания потоков (для правильного расчета включения partitions)
		beginPartitionNode: null,
		endPartitionNode: null,
		diagramElement: diagramElement,
	};
	return node;
}

// Создание связи
function createLink(relationship, node){
	return {
		relationship: relationship,
		node: node,
		name: getRelationshipName(relationship),
		notes: getRelationshipNotes(relationship),
	};	
}

// Получение имени связи
function getElementName( element ){
	if (!element) {
		return "";
	}
	return element.Name + element.ClassifierName + (element.ClassifierType ? " <"+element.ClassifierType+">" : "");
}

// Получение заметок элемента
function getElementNotes(diagramElement){
	if (!diagramElement || !diagramElement.Notes) {
		return "";
	}
	return diagramElement.Notes;
}

// Получение имени связи
function getRelationshipName( relationship ){
	if (!relationship || !relationship.connector || !relationship.connector.Name) {
		return "";
	}
	return relationship.connector.Name;
}

// Получение заметок связи
function getRelationshipNotes(relationship){
	if (!relationship || !relationship.connector || !relationship.connector.Notes) {
		return "";
	}
	return relationship.connector.Notes;
}

// Сброс признака обработки
function resetNodeProcessed(nodes){
	nodes.forEach(function(node){
		node.isProcessed = false;
	});
}

// Проверка готовности элемента к обработке
function isReadyToProcess(node){
	return !node.outcomeLinks.length || node.outcomeLinks.every(outcome => {
		/*
		if (!outcome || !outcome.node) {
			logMessage("!!!!!!! isReadyToProcess: "+node.name+"  node.outcomeLinks.length="+node.outcomeLinks.length+"  outcome.node: " + (outcome ? outcome.node : "null"), "INFO");
		}
		*/
		return outcome.node.isProcessed
	});
}

// Удаление связи между двумя узлами
function removeNode(mainNode, removedNode){
	// Удаляем связи из первого узла на removedNode
	mainNode.outcomeLinks = mainNode.outcomeLinks.filter(outcome => outcome.node.id != removedNode.id);
	// Добавляем связи из второго узла на связи с первым узлом
	// var removedOutcomeLinks = removedNode.outcomeLinks.filter(secondOutcome => !mainNode.outcomeLinks.some(firstOutcome => firstOutcome.node.id == secondOutcome.node.id));
	mainNode.outcomeLinks = mainNode.outcomeLinks.concat(removedNode.outcomeLinks);
	// Убираем дубли
	mainNode.outcomeLinks = mainNode.outcomeLinks.reduce((result, item) => {
		return result.some(link => link.node.id == item.node.id) ? result : [... result, item];
	}, []);			
	// Меняем ссылки у последующих элементов на mainNode:
	var nextNodes = removedNode.outcomeLinks.map(outcome => outcome.node);
	nextNodes.forEach( (nextNode) => {
		nextNode.incomeLinks.filter(income => income.node.id == removedNode.id).forEach(income => income.node = mainNode);
		// убираем дубликаты
		nextNode.incomeLinks = nextNode.incomeLinks.reduce((result, item) => {
			return result.some(link => link.node.id == item.node.id) ? result : [... result, item];
		}, []);			
	});
	/*
	// Узлы, которые ссылались на removedNode, теперь должны ссылаться на mainNode, за исключением связи с mainNode
	removedNode.incomeLinks.filter(income => income.node.diagramElement.ElementID != mainNode.diagramElement.ElementID).forEach(income => {
		income.node.outcomeLinks = income.node.outcomeLinks.filter(outcome => outcome.node.diagramElement.ElementID != removedNode.diagramElement.ElementID);
		income.node.outcomeLinks.push(createLink(income.relationship, mainNode));
	});
	*/
	removedNode.isDeleted = true;
	return mainNode;
}

// Объединение двух узлов графа
function joinNodes(firstNode, secondNode){
	var outcome = firstNode.outcomeLinks.find(outcome => outcome.node.id == secondNode.id);
	firstNode.code += (outcome ? getNarrowCode(outcome) : "") + getNodeCode(secondNode);
	logMessage("joinNodes:  firstNode=<"+firstNode.name + "> (code "+firstNode.code.length+") outcome=["+firstNode.outcomeLinks.map(outcome => "<"+outcome.node.name+">").join(", ")+"], income=["+firstNode.incomeLinks.map(income => "<"+income.node.name+">").join(", ")+"]    secondNode=<"+secondNode.name+">  (code "+secondNode.code.length+") outcomeLinks=["+secondNode.outcomeLinks.map(outcome => "<"+outcome.node.name+">").join(", ")+"]  incomeLinks=["+secondNode.incomeLinks.map(income => "<"+income.node.name+">").join(", ")+"] secondNode.isDeleted=" + secondNode.isDeleted,"TRACE");
	// Удаляем связь со вторым узлом
	removeNode(firstNode, secondNode);
	return firstNode;
}


// Получение типа обрабатываемого элемента
function getNodeProperties(node){
	const TOKEN_TYPES = [
		{
			condition: {
				type: "value",
				stereotype: "value",
				subtype: -1,
				kind: "value",
			},
			properties: {
				type: "token type",
				stereotype: "token stereotype",
				header: "",
				footer: "",
			}
		},
		{
			condition: {
				type: "StateNode",
				stereotype: null,
				subtype: 100,
				kind: null,
			},
			properties: {
				type: "start",
				stereotype: "",
				collapse: collapseStartNode,
			}
		},
		{
			condition: {
				type: "StateNode",
				stereotype: null,
				subtype: 101,
				kind: null
			},
			properties: {
				type: "stop",
				stereotype: "",
				collapse: collapseStopNode,
			}
		},
		{
			condition: {
				type: "Action",
				stereotype: null,
				subtype: 0,
				kind: "AcceptEvent"
			},
			properties: {
				type: ":",
				stereotype: "acceptEvent",
				collapse: collapseActionNode,
			}
		},
		{
			condition: {
				type: "Action",
				stereotype: null,
				subtype: 0,
				kind: "SendSignal"
			},
			properties: {
				type: ":",
				stereotype: "sendSignal",
				collapse: collapseActionNode,
			}
		},
		{
			condition: {
				type: "Action",
				stereotype: null,
				subtype: 0,
				kind: "CallOperation"
			},
			properties: {
				type: ":",
				stereotype: "procedure",
				collapse: collapseActionNode,
			}
		},
		{
			condition: {
				type: "Action",
				stereotype: null,
				subtype: 0,
				kind: "CallBehavior"
			},
			properties: {
				type: ":",
				stereotype: "procedure",
				collapse: collapseActionNode,
			}
		},
		{
			condition: {
				type: "Action",
				stereotype: null,
				subtype: 0,
				kind: null,
			},
			properties: {
				type: ":",
				stereotype: "",
				collapse: collapseActionNode,
			}
		},
		{
			condition: {
				type: "Event",
				stereotype: null,
				subtype: 0,
				kind: ""
			},
			properties: {
				type: ":",
				stereotype: "sendSignal",
				collapse: collapseActionNode,
			}
		},
		{
			condition: {
				type: "Event",
				stereotype: null,
				subtype: 1,
				kind: ""
			},
			properties: {
				type: ":",
				stereotype: "acceptEvent",
				collapse: collapseActionNode,
			}
		},
		{
			condition: {
				type: "Decision",
				stereotype: null,
				subtype: 0,
				kind: ""
			},
			properties: {
				type: "if",
				stereotype: "",
				collapse: collapseDecisionNode,
			}
		},
		{
			condition: {
				type: "Note",
				stereotype: null,
				subtype: 0,
				kind: null
			},
			properties: {
				type: "note",
				stereotype: "",
				collapse: collapseNoteNode,
			}
		},
		{
			condition: {
				type: "Text",
				stereotype: null,
				subtype: 0,
				kind: null
			},
			properties: {
				type: "note",
				stereotype: "",
				collapse: collapseNoteNode,
			}
		},
		{
			condition: {
				type: "Synchronization",
				stereotype: null,
				subtype: 0,
				kind: null
			},
			properties: {
				type: "fork",
				stereotype: "",
				collapse: collapseSynchronizationNode,
			}
		},
		{
			condition: {
				type: "ActivityParameter",
				stereotype: null,
				subtype: null,
				kind: null
			},
			properties: null
		},	
		{
			condition: {
				type: "Activity",
				stereotype: null,
				subtype: null,
				kind: null
			},
			properties: {
				type: "partition",
				stereotype: "",
				collapse: null,
			}
		},	
	];

	var elementKind = "";
	for (var j=0; j < node.diagramElement.CustomProperties.Count; j++){
		var prop = node.diagramElement.CustomProperties.GetAt(j);
		if (prop.Name == "kind") {
			elementKind = prop.Value;
		}
	}
	const elementCondition = {
		type: node.diagramElement.Type,
		stereotype: node.diagramElement.Stereotype,
		subtype: node.diagramElement.Subtype,
		kind: elementKind
	};
	var tokenType = TOKEN_TYPES.find( token => 
		elementCondition.type === token.condition.type &&
		( token.condition.stereotype === null || elementCondition.stereotype === token.condition.stereotype) &&
		( token.condition.subtype === null || elementCondition.subtype === token.condition.subtype) &&
		( token.condition.kind === null || elementCondition.kind === token.condition.kind)
	);
	if (!tokenType){
		logMessage("Не найдена информация PlantUML для node=<"+node.name+"> шаблон поиска:"+JSON.stringify(elementCondition), "WARNING");
	}
	return tokenType && tokenType.properties;
}

function generateActivityDiagramAllElementCode(nodes, diagram, diagramConfig) {
	var code = "";
	//
	collapseGraph(nodes, diagram, diagramConfig);
	var code = nodes.filter(rootNode => rootNode.isRoot).map(node => getNodeCode(node)).join("\n");
	return code;
}


// Свертывание графа элементов
function collapseGraph(nodes, diagram, diagramConfig) {
	// Сбрасываем признак обработки
	resetNodeProcessed(nodes);
	//
	var beforeLength = 0;
	var afterLength = nodes.filter(n => !n.isProcessed || (!n.isDeleted && !n.isRoot)).length;
	while (afterLength && beforeLength != afterLength ){
		beforeLength = afterLength;
		// logMessage("*** Не обработано "+beforeLength+" элементов.","TRACE");
		nodes.forEach(function( node ){
			collapseNode( node, nodes);
		});
		afterLength = nodes.filter(n => !n.isProcessed || (!n.isDeleted && !n.isRoot)).length;
	}
	if (afterLength) {
		var notCollapsed = nodes.filter(n => !n.isProcessed || (!n.isDeleted && !n.isRoot));
		logMessage("Не удалось выполнить свертку " + afterLength + " элементов: ["+notCollapsed.map(node => node.name).join(", ")+"]", "ERROR");
	} else {
		logMessage("Свертка элементов выполнена полностью", "INFO");
	}
}

function getNoteNodeCode(node, excludeNodeNotes){
	var code = "";
	if (node.noteNodes && node.noteNodes.length){
		code += node.noteNodes.map(note => getNoteNodeCode(note)).join("");
		// Отмечаем заметку обработанной
		node.noteNodes.forEach(note => {
			note.isProcessed = true;
			note.isDeleted = true;
		});
	}
	if (!excludeNodeNotes && node.notes) {
		code += "note right\n" + formatNoteForPlantUML(node.notes) + "\n" + "end note\n";
	}
	return code;
}

function collapseStartNode(node, nodes){
	if (!isReadyToProcess(node)) {
		// Есть не обработанные элементы и нужно дождаться их обработки
		return;
	}
	node.code = "start\n" + getNoteNodeCode(node);
	// Сворачиваем
	if (node.outcomeLinks.length == 1) {
		// node.code += node.outcomeLinks.map(outcome => outcome.node.code).join("");
	} else if (node.outcomeLinks.length > 1) {
		node.code = "fork\n";
		node.code += node.outcomeLinks.map(outcome => getNodeCode(outcome.node)).join("fork again \n");
		node.code = "end fork\n";
		node.outcomeLinks.forEach(outcome => { removeNode(node, outcome.node); });
	}
	node.isProcessed = true;
	return [];
}

function collapseStopNode(node, nodes){
	node.code = "stop\n" + getNoteNodeCode(node);
	node.isProcessed = true;
	if (node.outcomeLinks.length) {
		logMessage("Ошибка в свертке графа: Stop элемент "+node.name + " не должен иметь исходящие связи.","ERROR");
	}
	return [];
}

function collapseActionNode(node, nodes){
	// Всегда можем обработать текущий
	var code = getLabelNodeCode(node) + 
		":" + node.name + 
		(node.notes ? "\n=====\n"+formatNoteForPlantUML(node.notes) : "") +
		";" + 
		(node.properties.stereotype ? " <<" + node.properties.stereotype + ">>" : "") + 
		"\n"+
		getNoteNodeCode(node, true);
		// + getNoteNodeCode(node);
	if (node.outcomeLinks.length == 0) {
		node.code = code;
		node.code += "kill\n";
		node.isProcessed = true;
		return [];
	} else if (node.outcomeLinks.length == 1) {
		node.code = code;
		node.isProcessed = true;
		return [];
		/*
		node.code += getNarrowCode(node.outcomeLinks[0]);
		var nextNode = node.outcomeLinks[0].node;
		if (nextNode.incomeLinks.length == 1) {
			// Не добавляем код, если у следующего элемента две входных стрелки
			node = joinNodes(node, nextNode);
		}
		*/
	} else if (isReadyToProcess(node) && node.outcomeLinks.length > 1) {
		var pattern = graphPatternSplit(node);
		if (pattern) {
			node.code = code;
			node.code += "split\n";
			node.code += node.outcomeLinks.map(outcome => getNarrowCode(outcome) + getNodeCode(outcome.node)).join("split again \n");
			node.code += "end split\n";
			node.outcomeLinks.forEach(outcome => { removeNode(node, outcome.node); });
			// node = joinNodes(node, pattern.nextNode);
			node.isProcessed = true;
			return [];
		} else {
			logMessage("Не поддерживаемая конструкция связей для collapseActionNode. Элемент <"+node.name+"> имеет node.outcomeLinks="+node.outcomeLinks.map(outcome => "<"+outcome.node.name+">").join(", ")+".","ERROR");
			return null;
		}
	}
}

function findSecondLevelNode(node){
	var secondLevelNode = null;
	node.outcomeLinks.forEach(outcome => {
		if (outcome.node.outcomeLinks.length){
			secondLevelNode = outcome.node.outcomeLinks[0].node;
			return secondLevelNode;
		}
	});
	return secondLevelNode;
}

function collapseNoteNode(node, nodes){
	// Заметка всегда обрабатывается и не зависит от связей
	node.code = "note\n" + node.notes + "\n" + "end note\n";
	node.isProcessed = true;
	return [];
}

// Получение условия для case
function getCaseCondition(outcome){
	if (!outcome || !outcome.name){
		return "";
	}
	return "("+formatTextForPlantUML(outcome.name)+")";
}

// Паттерин "split" с одним исходящим элементом
function graphPatternSplit(node){
	if (!node.outcomeLinks.length) {
		return null;
	}
	var bodyNode = node.outcomeLinks[0].node;
	var nextNode = bodyNode ? bodyNode.outcomeLinks[0].node : null;
	var isSplit = nextNode && node.outcomeLinks.every(out => !out.node.outcomeLinks.length || out.node.outcomeLinks[0].node.id == nextNode.id);
	if (isSplit) {
		return {nextNode: nextNode};
	}
	return null;
}

// Паттерн "repeat"
function graphPatternRepeat(node){
	if (node.outcomeLinks.length != 2) {
		return false;
	}
	function checkNodesRepeat(repeatNode, actionNodeOutcome, nextNode){
		if (nextNode.outcomeLinks.some(outcome => outcome.node.id == repeatNode.id)) {
			return false;
		}
		if (actionNodeOutcome.node.incomeLinks.length != 2) {
			return false;
		}
		// Одна из ссылок должны быть из условия
		if (actionNodeOutcome.node.incomeLinks.every(income => income.node.id != repeatNode.id)) {
			return false;
		}
		if (actionNodeOutcome.node.outcomeLinks.length != 1) {
			return false;
		}
		if (actionNodeOutcome.node.outcomeLinks[0].node.id == repeatNode.id) {
			return {actionNodeOutcome: actionNodeOutcome, nextNode: nextNode};
		}
		return null;
	}
	var result = checkNodesRepeat(node, node.outcomeLinks[0], node.outcomeLinks[1].node);
	if (result) {
		return result;
	}
	result = checkNodesRepeat(node, node.outcomeLinks[1], node.outcomeLinks[0].node);
	if (result) {
		return result;
	}
	return null;
}

// Паттерн "while"
function graphPatternWhile(node){
	if (node.outcomeLinks.length != 2) {
		return false;
	}
	function checkNodesWhile(whileNode, actionNodeOutcome, nextNode){
		if (nextNode.outcomeLinks.some(outcome => outcome.node.id == whileNode.id)) {
			return false;
		}
		if (actionNodeOutcome.node.outcomeLinks.length != 1) {
			return false;
		}
		if (actionNodeOutcome.node.outcomeLinks[0].node.id == whileNode.id) {
			return {actionNodeOutcome: actionNodeOutcome, nextNode: nextNode};
		}
		return null;
	}
	var result = checkNodesWhile(node, node.outcomeLinks[0], node.outcomeLinks[1].node);
	if (result) {
		return result;
	}
	result = checkNodesWhile(node, node.outcomeLinks[1], node.outcomeLinks[0].node);
	if (result) {
		return result;
	}
	return null;
}

// Паттерн "if"
function graphPatternIf(node){
	if (node.outcomeLinks.length != 2) {
		return false;
	}
	function checkNodesShortIf(actionNodeOutcome, combinedNodeOutcome){
		if (combinedNodeOutcome.node.incomeLinks.length < 2) {
			return false;
		}
		if (actionNodeOutcome.node.outcomeLinks.length != 1) {
			return false;
		}
		if (actionNodeOutcome.node.outcomeLinks[0].node.id == combinedNodeOutcome.node.id) {
			return {actionNodeOutcome1: actionNodeOutcome, actionNodeOutcome2: null, combinedNode: combinedNodeOutcome.node};
		}
		return null;
	}
	function checkNodesFullIf(actionNodeOutcome1, actionNodeOutcome2){
		// logMessage("!!! checkNodesFullIf <"+node.name+"> actionNode1: <"+actionNodeOutcome1.node.name + "> actionNode1.outcomeLinks=" + actionNodeOutcome1.node.outcomeLinks.map(outcome => "<"+outcome.node.name+">").join(", ") + " actionNode2: <"+actionNodeOutcome2.node.name + "> actionNode2.outcomeLinks=" + actionNodeOutcome2.node.outcomeLinks.map(outcome => "<"+outcome.node.name+">").join(", "),"TRACE");
		if (!actionNodeOutcome1.node.outcomeLinks.length || !actionNodeOutcome2.node.outcomeLinks.length) {
			var combinedNode = (actionNodeOutcome1.node.outcomeLinks.length ? actionNodeOutcome1.node.outcomeLinks[0].node :
				(actionNodeOutcome2.node.outcomeLinks.length ? actionNodeOutcome2.node.outcomeLinks[0].node : null)
			);
			return {actionNodeOutcome1: actionNodeOutcome1, actionNodeOutcome2: actionNodeOutcome2, combinedNode: combinedNode};
		}
		if (actionNodeOutcome1.node.outcomeLinks.length != 1) {
			return false;
		}
		if (actionNodeOutcome2.node.outcomeLinks.length != 1) {
			return false;
		}
		if (actionNodeOutcome1.node.outcomeLinks[0].node.id == actionNodeOutcome2.node.outcomeLinks[0].node.id) {
			return {actionNodeOutcome1: actionNodeOutcome1, actionNodeOutcome2: actionNodeOutcome2, combinedNode: actionNodeOutcome1.node.outcomeLinks[0].node};
		}
		return null;
	}
	var result = checkNodesShortIf(node.outcomeLinks[0], node.outcomeLinks[1]);
	if (result) {
		return result;
	}
	result = checkNodesShortIf(node.outcomeLinks[1], node.outcomeLinks[0]);
	if (result) {
		return result;
	}
	result = checkNodesFullIf(node.outcomeLinks[0], node.outcomeLinks[1]);
	if (result) {
		return result;
	}
	return null;
}

function collapseDecisionNode(node, nodes){
	if (!isReadyToProcess(node)) {
		// Есть не обработанные элементы и нужно дождаться их обработки
		return null;
	}
	// Сворачиваем
	if (node.outcomeLinks.length <= 1) {
		return null;
	}
	if (node.outcomeLinks.length == 2) {
		var pattern = graphPatternRepeat(node);
		if (pattern) {
			pattern.actionNodeOutcome.node.code = "repeat\n" + 
				getNarrowCode(pattern.actionNodeOutcome) + 
				getNodeCode(pattern.actionNodeOutcome.node) + 
				getNarrowCode(pattern.actionNodeOutcome.node.outcomeLinks.find(outcome => outcome.node.id == node.id)) + 
				"repeat while ("+
				node.name + 
				")" + 
				(node.properties.stereotype ? " <<" + node.properties.stereotype + ">>" : "") + 
				"\n" + 
				getNoteNodeCode(node);
			removeNode(pattern.actionNodeOutcome.node, node);
			// Убираем ссылку на самого себя, которая появится после удаления узла выше
			pattern.actionNodeOutcome.node.outcomeLinks = pattern.actionNodeOutcome.node.outcomeLinks.filter(outcome => outcome.node.id != pattern.actionNodeOutcome.node.id);
			pattern.actionNodeOutcome.node.incomeLinks = pattern.actionNodeOutcome.node.incomeLinks.filter(income => income.node.id != pattern.actionNodeOutcome.node.id);
			node.isProcessed = true;
			return [node];
		}
		pattern = graphPatternWhile(node);
		if (pattern) {
			node.code = "while (" +
				node.name + 
				")" + 
				(node.properties.stereotype ? " <<" + node.properties.stereotype + ">>" : "") + 
				"\n" +
				getNoteNodeCode(node) +
				getNarrowCode(pattern.actionNodeOutcome) + 
				getNodeCode(pattern.actionNodeOutcome.node) + 
				getNarrowCode(pattern.actionNodeOutcome.node.outcomeLinks.find(outcome => outcome.node.id == node.id)) +
				"endwhile\n";
			removeNode(node, pattern.actionNodeOutcome.node);
			// Убираем ссылку на самого себя, которая появится после удаления узла выше
			node.outcomeLinks = node.outcomeLinks.filter(outcome => outcome.node.id != node.id);
			node.incomeLinks = node.incomeLinks.filter(income => income.node.id != node.id);
			node.isProcessed = true;
			logMessage("while:  node=<"+node.name + "> ("+node.code.length+") outcomeLinks=["+node.outcomeLinks.map(outcome => "<"+outcome.node.name+">").join(", ")+"]   nextNode=<"+pattern.nextNode.name+">  ("+pattern.nextNode.code.length+") outcomeLinks=["+pattern.nextNode.outcomeLinks.map(outcome => "<"+outcome.node.name+">").join(", ")+"]  incomeLinks=["+pattern.nextNode.incomeLinks.map(income => "<"+income.node.name+">").join(", ")+"] nextNode.isDeleted=" + pattern.nextNode.isDeleted,"TRACE");
			return [pattern.actionNodeOutcome.node];
		}
		pattern = graphPatternIf(node);
		if (pattern) {
			var actionNodeOutcome1 = pattern.actionNodeOutcome1;
			var actionNodeOutcome2 = pattern.actionNodeOutcome2;
			var combinedNode = pattern.combinedNode;
			var actionNode1_code = (actionNodeOutcome1 ? getNodeCode(actionNodeOutcome1.node) : "");
			var actionNode2_code = (actionNodeOutcome2 ? getNodeCode(actionNodeOutcome2.node) : "");

			node.code = "if ("+ node.name + ") then "+getCaseCondition(actionNodeOutcome1)+"\n" + getNoteNodeCode(node) +
				actionNode1_code +
				"else "+getCaseCondition(actionNodeOutcome2)+"\n" + 
				actionNode2_code +
				"endif\n";
			var removed = []
			if (actionNodeOutcome1) {
				node = removeNode(node, actionNodeOutcome1.node);
				removed.push(actionNodeOutcome1.node);
			}
			if (actionNodeOutcome2) {
				node = removeNode(node, actionNodeOutcome2.node);
				removed.push(actionNodeOutcome2.node);
			}
			/* Нельзя, так как может быть goto на этот узел:
			if (combinedNode) {
				node = joinNodes(node, combinedNode);
			}
			*/
			node.isProcessed = true;
			return removed;
		} else {
			logMessage("Не поддерживаемая конструкция связей для collapseDecisionNode. Элемент <"+node.name+"> имеет node.outcomeLinks="+node.outcomeLinks.map(outcome => "<"+outcome.node.name+">").join(",")+".","ERROR");
			return [];
		}
	} else if (node.outcomeLinks.length > 2) {
		var nextNode = findSecondLevelNode(node);
		// logMessage("!!!!! switch node = "+node.name + " outlen=" + node.outcomeLinks.length,"TRACE");
		node.code = "switch ("+ node.name + ")\n" + getNoteNodeCode(node) +
			node.outcomeLinks.map(outcome => "case "+getCaseCondition(outcome)+"\n" + getNodeCode(outcome.node)).join("") +
			"endswitch\n";
		var removed = node.outcomeLinks.map(outcome => outcome.node);
		node.outcomeLinks.forEach(outcome => { removeNode(node, outcome.node); });
		/*
		if (nextNode){
			node = joinNodes(node, nextNode);
		}
		*/
		node.isProcessed = true;
		return removed;
	}
}

// Получение кода метки шага
function getLabelNodeCode(node){
	if (node.incomeLinks.length > 1) {
		return "label node" + node.id + "\n";
	}
	return "";
}

// Получение кода для перехода на узел
function getGotoNodeCode(node){
	// logMessage("*** Добавление goto на узел  <"+node.name + "> isProcessed="+node.isProcessed + " isDeleted="+node.isDeleted+ " isRoot="+node.isRoot+ " длина кода "+node.code.length,"TRACE");
	// Чтобы корректно работало форматирование, нужно добавлять label
	return "label node" + node.id + "_" + Math.floor(1 + Math.random()*1000).toString(10) + "\n" + 
		"goto node" + node.id + "\n";
}

// Получение кода узла в зависимости от состояния
function getNodeCode(node){
	var code = "";
	if (node.beginPartitionNode) {
		code += "partition " + node.beginPartitionNode.name + " {\n";
		node.beginPartitionNode.isDeleted = true;
		node.beginPartitionNode.isProcessed = true;
		// logMessage("*** Добавлно начало региона <"+node.beginPartitionNode.name+"> для узла <"+node.name+">", "INFO");
	}
	// Добавляем до основного кода
	if (node.endPartitionNode) {
		code += " }\n";
		node.endPartitionNode.isDeleted = true;
		node.endPartitionNode.isProcessed = true;
		// logMessage("*** Добавлен конец региона <"+node.endPartitionNode.name+"> для узла <"+node.name+">", "INFO");
	}
	if (!!node.isDeleted){
		return code+(node.incomeLinks.length > 1 ? getGotoNodeCode(node) : "");
	}
	return code+node.code;
}

// Получение кода для связи между узлами
function getNarrowCode(link){
	if (!link){
		return "";
	}
	var text = [link.name,(link.notes ? "<i>"+link.notes: null)].filter(s => s).join("\n");
	if (!text) {
		return "";
	}
	return "-> " + text + ";\n";
}

function patternSynchronization(node){
	if (node.outcomeLinks.length <= 1) {
		node.code = "";
		node.isProcessed = true;
		return false;
	}
	return node.outcomeLinks.every(outcome1 => !outcome1.node.outcomeLinks.length || 
		node.outcomeLinks.every(outcome2 => !outcome2.node.outcomeLinks.length || outcome1.node.outcomeLinks[0].node.id == outcome2.node.outcomeLinks[0].node.id));
}

function collapseSynchronizationNode(node, nodes){
	if (!isReadyToProcess(node)) {
		// Есть не обработанные элементы и нужно дождаться их обработки
		return null;
	}
	if (!patternSynchronization(node)){
		return null;
	}
	node.code = "fork\n" + getNoteNodeCode(node);
	node.code += node.outcomeLinks.map(outcome => getNarrowCode(outcome) + getNodeCode(outcome.node) ).join("fork again \n");
	node.code += "end fork\n";
	var removed = node.outcomeLinks.map(outcome => outcome.node);
	node.outcomeLinks.forEach(outcome => { removeNode(node, outcome.node); });
	node.isProcessed = true;
	return removed;
}

// Свертка последовательности элементов
function collapseSequenceNodes(node, nodes){
	if (!isReadyToProcess(node)) {
		// Есть не обработанные элементы и нужно дождаться их обработки
		return null;
	}
	// logMessage("BEGIN collapseSequenceNodes <"+node.name + "> ","TRACE");
/*	
*/	
	if (node.incomeLinks.length > 1 && node.incomeLinks.some(income => !income.node.isProcessed)) {
		return null;
	}
	if (node.outcomeLinks.length != 1) {
		return null;
	}
	var nextNode = node.outcomeLinks[0].node;
	// Обработка в другой процедуре
	if (nextNode.isDeleted) {
		return null;
	}
	// logMessage("BEGIN collapseSequenceNodes <"+node.name + "> nextNode=<"+nextNode.name+"> nextNode.incomeLinks=["+nextNode.incomeLinks.map(income => income.node.name).join(", ")+ "]"+"> nextNode.outcomeLinks=["+nextNode.outcomeLinks.map(outcome => outcome.node.name).join(", ")+ "]","TRACE");
	if (nextNode.incomeLinks.length > 1) {
		return null;
	}
	if (!nextNode.incomeLinks.every(income => income.node.isProcessed)) {
		return null;
	}
	node = joinNodes(node, nextNode);
	logMessage("collapseSequenceNodes <"+node.name + "> nextNode=<"+nextNode.name+"> nextNode.incomeLinks=["+nextNode.incomeLinks.map(income => income.node.name).join(", ")+ "]"+"> nextNode.outcomeLinks=["+nextNode.outcomeLinks.map(outcome => outcome.node.name).join(", ")+ "]","TRACE");
	return [nextNode];
}

// Свертка последовательности элементов с удаленными элементами
function collapseSequenceNodesWithDeletedNode(node, nodes){
	if (!isReadyToProcess(node)) {
		// Есть не обработанные элементы и нужно дождаться их обработки
		return null;
	}
	if (node.outcomeLinks.length != 1) {
		return null;
	}
	var nextNode = node.outcomeLinks[0].node;
	if (!nextNode.incomeLinks.every(income => income.node.isProcessed)) {
		return null;
	}
	if (!nextNode.isDeleted) {
		return null;
	}
	node = joinNodes(node, nextNode);
	logMessage("collapseSequenceNodesWithDeletedNode <"+node.name + "> nextNode=<"+nextNode.name+"> nextNode.incomeLinks=["+nextNode.incomeLinks.map(income => income.node.name).join(", ")+ "]"+"> nextNode.outcomeLinks=["+nextNode.outcomeLinks.map(outcome => outcome.node.name).join(", ")+ "]","TRACE");
	return [nextNode];
}

// Свертка нескольких входящих потоков
function collapseIncomeParallelNodes(node, nodes){
	if (!isReadyToProcess(node)) {
		// Есть не обработанные элементы и нужно дождаться их обработки
		return null;
	}
	if (node.incomeLinks.length <= 1) {
		return null;
	}
	if (node.incomeLinks.some(income => !income.node.isProcessed)) {
		return null;
	}
	if (node.outcomeLinks.length != 1) {
		return null;
	}
	var nextNode = node.outcomeLinks[0].node;
	if (nextNode.incomeLinks.some(income => !income.node.isProcessed)) {
		return null;
	}
	node = joinNodes(node, nextNode);
	logMessage("collapseIncomeParallelNodes <"+node.name + "> nextNode=<"+nextNode.name+"> nextNode.incomeLinks=["+nextNode.incomeLinks.map(income => income.node.name).join(", ")+ "]"+"> nextNode.outcomeLinks=["+nextNode.outcomeLinks.map(outcome => outcome.node.name).join(", ")+ "]","TRACE");
	return [nextNode];
}

// Свертывание одного элемента
function collapseNode(node, nodes){
	if (node.isDeleted) {
		return;
	}
	var removed = [];
	if (!node.properties){
		logMessage("Не найдено описание параметров для узла <"+node.name + ">", "ERROR");
	} else if (!node.properties.collapse) {
		logMessage("Не указана функция свертки для узла <"+node.name + ">", "ERROR");
	} else if (!node.isProcessed) {
		var result = node.properties.collapse(node, nodes);
		if (result) {
			removed = removed.concat( result );
		}
	}
	// Свертка сложных конструкций
	[
		collapseSequenceNodes,
		collapseIncomeParallelNodes,
		collapseSequenceNodesWithDeletedNode,
	].forEach( (collapseFunction) => {
		var result = collapseFunction(node, nodes)
		if (result) {
			removed = removed.concat( result );
		}
	});	
	//
	logMessage("Collapse node <"+node.name + "> isProcessed="+node.isProcessed + " isDeleted="+node.isDeleted+ " isRoot="+node.isRoot+ " длина кода "+node.code.length,"TRACE");
	logMessage("     noteNodes= "+(node.noteNodes ? node.noteNodes.map(note => "<"+(note.name ? note.name : note.notes.slice(0,20))+">").join(", ") : ""),"TRACE")
	logMessage("     income.nodes= "+node.incomeLinks.map(income => "<"+income.node.name+">").join(", "),"TRACE")
	logMessage("     outcome.nodes= "+node.outcomeLinks.map(outcome => "<"+outcome.node.name+">").join(", "),"TRACE")
	logMessage("     removedNodes= "+removed.map(node => "<"+node.name+">").join(", "),"TRACE")
}

!INC Local Scripts.EAConstants-JavaScript

/*
 * Script Name: 
 * Author: 
 * Purpose: 
 * Date: 
 */

var _fileSystemObject = null;
function getFileSystemObject(){
	if (!_fileSystemObject){
        _fileSystemObject = new COMObject("Scripting.FileSystemObject");
	}
	return _fileSystemObject;
}

// Определение слеша по строке для совместимости с MacOS
function GetSlash( samplePath ){
	if (samplePath && samplePath.includes("/")) {
		return "/";
	} else {
		return "\\"
	}
}

// Формирование пути к файлу на основе двух частей
function MakeFilePath( first, second ){
	return (first.trim().slice(-1) != GetSlash(first) ? first.trim() + GetSlash(first) : first.trim()) + second;
//	return getFileSystemObject().BuildPath(first, second);
}

/**
 * Копирование файла
 */ 
function CopyFile( sourceFileName, destinationFileName){
    var fileSystemObject = getFileSystemObject();
	return fileSystemObject.CopyFile(sourceFileName, destinationFileName, true);
}

/**
 * Сохраняет текст в файл
 */
function saveToFile( textData, fileName, backupExtension, filterFileDialog ) {
    var fileSystemObject = getFileSystemObject();
	var fullFileName = fileSystemObject.GetAbsolutePathName(fileName);
    logMessage("Сохранение данных в файл: " + fullFileName, "INFO");

    // Создаем резервную копию если файл существует
    if (backupExtension) {
        if (fileSystemObject.FileExists(fullFileName)) {
            var backupFileName = fullFileName + backupExtension;
            fileSystemObject.CopyFile(fullFileName, backupFileName, true);
            logMessage("Создана резервная копия: " + backupFileName, "INFO");
        }
    }

    // Создаем файл с кодировкой UTF-8 (третий параметр = true для Unicode)
    var file = fileSystemObject.CreateTextFile(fullFileName, true, true);
	if (!file) {
		var fileNameOnly = fileSystemObject.GetFileName(fullFileName);
        logMessage("Ошибка создания файла <"+ fullFileName + "> в указанной папке.", "WARNING");
		var fullFileName = getFileNameDialog( (filterFileDialog ? filterFileDialog : "All Files (*.*)|*.*||"), fileNameOnly);
        logMessage("Указан файл <"+ fullFileName + "> для сохранения.", "INFO");
		if (!fullFileName) {
			throw new Error("Файл для сохранения данных не выбран. Данные не сохранены в файл.");
		}
		file = fileSystemObject.CreateTextFile(fullFileName, true, true);
		if (!file) {
			throw new Error("Ошибка создания указанного файла <"+ fullFileName + ">. Данные не сохранены в файл.");
		}
	}
    file.Write(textData);
    file.Close();

    return fullFileName;
}

function getFileNameDialog(filterFileDialog, filename){
	var filterString = (filterFileDialog ? filterFileDialog : "CSV Files (*.csv)|*.csv|All Files (*.*)|*.*||");
	var filterindex = 1; 
	var flags = 0x802; // 'OFN_OVERWRITEPROMPT
	var initialDirectory = "";
	var openOrSave = 1
	var project as EA.Project;
	project = Repository.GetProjectInterface();
	var filepath = project.GetFileNameDialog (filename, filterString, filterindex, flags, initialDirectory, openOrSave);
	return filepath;
}

// Проверка существования каталога, в котором нужно будет создавать файл
function existsDirectory(fileName) {
    var fileSystemObject = getFileSystemObject();
	// Может быть указано относительно имя
	var fullFileName = fileSystemObject.GetAbsolutePathName(fileName);
	var folder = fileSystemObject.GetParentFolderName(fullFileName);
	return fileSystemObject.FolderExists(folder);
}
